		["Zhevra Runners graze north and east of town."] = "Zhevra-Läufer grasen nördlich und östlich des Orts.",
		["{area:1898} cultists"] = "Kultisten in {area:1898}",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn."] = "{area:380} ist deine Basis für diesen Guide. Alle, die du brauchst, stehen nur wenige Schritte vom Gasthaus entfernt.",
		["{npc:3442} in {area:392}: later, on the way"] = "{npc:3442} in {area:392}: später, auf dem Weg",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: Die Konsole ist in {area:382}, später",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: Die Harpyien kommen später, in {area:383}",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} lagert an der Straße nach Osten Richtung {area:392}.",
		["{npc:5878} camps beside the road from the {area:380} to {area:392}. The {object:58369} sits in the south of the Razormane camp just north of him."] = "{npc:5878} lagert an der Straße von {area:380} nach {area:392}. {object:58369} steht im Süden des Lagers der Grimmhauer gleich nördlich von ihm.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} macht aus dem Teer und dem Beutel {item:6636}. Benutze es am Kohlenbecken neben ihm, um {npc:5893} sichtbar zu machen, töte sie für {item:6655} und leg die Glut dann ins Kohlenbecken.",
		["{npc:5900} waits on the riverbank south of {area:379}, across the bridge."] = "{npc:5900} wartet am Flussufer südlich von {area:379}, jenseits der Brücke.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} steht auf dem Kamm nördlich des Lagers der Grimmhauer.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, dein {item:5176} und {item:263412}",
		["{quest:1492}, on the dock"] = "{quest:1492}, am Kai",
		["{quest:3301}: the {area:228} in {zone:1421}, next guide"] = "{quest:3301}: {area:228} in {zone:1421}, nächster Guide",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["At the {area:2362}"] = "Am {area:2362}",
		["Fly to {area:1638}: {npc:3033} trains you on {area:1639}. Skyborne: fly back to {zone:1454} for the zeppelin afterwards."] = "Flieg nach {area:1638}: {npc:3033} bildet dich aus ({area:1639}). Himmelsgeborene: Flieg danach für den Zeppelin zurück nach {zone:1454}.",
		["Follow the lake shore south-east and swim out to {area:172}. Rot Hide gnolls cover the island; every type drops ichor. Stay out of {area:235} on its north side unless you go for the optional niche: the gnolls there are level 18-22."] = "Folge dem Seeufer nach Südosten und schwimm hinaus zur {area:172}. Gnolle der Moderfelle bevölkern die Insel; jede Art lässt Sekret fallen. Meide {area:235} auf der Nordseite, außer du willst die optionale Nische: Die Gnolle dort sind Stufe 18-22.",
		["Follow the lake shore south-east toward {area:172}: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "Folge dem Seeufer nach Südosten Richtung {area:172}: Die Schredder und Gezeitenjäger der Finsterflossen dort lassen die Murlocaugen fallen.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Folge der Straße nach Nordosten zum Haus der Yoricks bei {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "Folge der Straße nach Süden. Die {object:1627} steht daneben, nördlich von Pyrewood.",
		["Keep it: Thork at the {area:380}"] = "Behalte sie: Thork in {area:380}",
		["Keep it: {npc:2216} in {area:272}, a later guide"] = "Behalte sie: {npc:2216} in {area:272}, ein späterer Guide",
		["Mottled Worgs"] = "Scheckige Worgs",
		["Mottled Worgs prowl the hills around the house."] = "Scheckige Worgs streifen durch die Hügel um das Haus.",
		["North again to the Yoricks' house."] = "Wieder nach Norden zum Haus der Yoricks.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "Nördlich von {area:228}. {npc:1983} spukt auf dem {area:240}: Töte sie und geh dann über das Feld.",
		["South-east down the road to {area:233}. Protectors guard the outskirts and Mages the town; both drop pendants. Wizards and Watchers patrol the roads around it. Stay out of the middle, where {npc:2120} stands."] = "Die Straße nach Südosten hinunter nach {area:233}. Beschützer von Dalaran bewachen den Ortsrand und Magier von Dalaran den Ort; beide lassen Anhänger fallen. Hexer und Behüter von Dalaran patrouillieren auf den Straßen ringsum. Meide die Mitte, wo {npc:2120} steht.",
		["Speak with {npc:10540}, in Grommash Hold"] = "Sprich mit {npc:10540} in Grommash Hold",
		["Speak with {npc:3230}, in Grommash Hold"] = "Sprich mit {npc:3230} in Grommash Hold",
		["Talk to {npc:10540}"] = "Sprich mit {npc:10540}",
		["Talk to {npc:3230}"] = "Sprich mit {npc:3230}",
		["The Vile Fin Lakestalkers and Oracles sit on the lake shore south of the {area:237}, east of the {area:228}."] = "Die Seepirscher und Orakel der Finsterflossen sitzen am Seeufer südlich der Fähre ({area:237}), östlich vom Grabmal ({area:228}).",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "Rohrkolben und Speergras wachsen am Wasser im {object:172958}, östlich der Gasse.",
		["The {object:1593} lies at the ferry landing on the lake shore east of the {area:228}."] = "Das {object:1593} liegt an der Fähranlegestelle am Seeufer östlich vom Grabmal ({area:228}).",
		["The {object:177790} lies on the coast west of the {area:240}. It holds the {item:15882} for {quest:30}."] = "Die {object:177790} liegt an der Küste westlich vom {area:240}. Sie enthält den {item:15882} für {quest:30}.",
		["Vile Fin murlocs"] = "Murlocs der Finsterflossen",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["{area:1338} shore"] = "Ufer: {area:1338}",
		["{area:233} comes later, on the southern loop"] = "{area:233} kommt später, auf der südlichen Runde",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, aus einem {object:177785} im See",
		["{item:3317}: a rare drop from the gnolls"] = "{item:3317}: seltene Beute von den Gnollen",
		["{npc:11798} in {area:2361} flies druids there; then fly on to {zone:1454} for the zeppelin"] = "{npc:11798} in {area:2361} fliegt Druiden dorthin; flieg dann weiter nach {zone:1454} zum Zeppelin",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, am Schrein: {area:2362}",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}: für Quinn, am Ende auf der Straße nach Norden",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} wartet nordöstlich des Hauses. Eskortiere ihn zurück zu {npc:1950}; unterwegs greifen Worgs an.",
		["{npc:2121}: {quest:516}, on the south loop"] = "{npc:2121}: {quest:516}, auf der südlichen Runde",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} bildet in {area:159} Paladine aus, ein kurzer Weg die Straße hinauf nach Norden von den Zeppelintürmen. Für den Silberwald kommst du dieselbe Straße zurück.",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} und {npc:3347} führen den Alchemieladen in der Gasse; {npc:11046} ist nebenan.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, in Grommash Hold",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, eine Tour zu den Anführern der Horde",
		["{object:1599}, just east of the keep"] = "{object:1599}, gleich östlich der Burg",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, nächster Guide",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Hilf {npc:261366}: Bleib bei ihm, wenn {npc:261367} und die Marinesoldaten von {area:21} den Kamm heraufkommen",
		["At the {object:147538}: summons {quest:882}"] = "Am toten Baum: beschwört {quest:882}",
		["Bael'dun fortress"] = "Festung von Bael'dun",
		["Bristleback camps"] = "Lager der Borstennacken",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran ist im Stacheleberlager westlich der Straße angekettet.",
		["Down the {area:458} to {area:378} again."] = "Die {area:458} wieder hinunter zum {area:378}.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Füll {item:7766} am Wasserloch der Stacheleber",
		["Fly to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "Flieg nach {area:1638} und trainiere deine Ränge der Stufe 20: {npc:3033} ist auf der {area:1639}.",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "Flieg zum Trainieren nach {area:1638}: {npc:3033} ist auf der {area:1639}.",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["Follow the {area:458} south to {area:378}."] = "Folge der {area:458} nach Süden zum {area:378}.",
		["He gives you the {item:15826}"] = "Er gibt dir {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Als Nächstes bietet er {quest:1838} an (1838, Stufe 30): Sie erfordert {area:1717} und schickt dich durch ganz Kalimdor und die Östlichen Königreiche. Der Kriegerklassen-Guide {quest:1838} deckt sie ab.",
		["Head north from the {area:380} to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the {area:380}. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "Geh vom {area:380} nach Norden zum {area:384} und fülle {item:15842} am Teich am Glutnebelgipfel, dann zurück zu {npc:3448} im {area:380}. Kein {skill:182}? {npc:3490} neben ihm verkauft {item:2449}, je drei auf einmal, bis er neu auffüllt.",
		["Keep it: the {object:107045} is beside {area:272}"] = "Behalte sie: {object:107045} ist neben {area:272}",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Behalte sie: {npc:12696} in {zone:1440}, nächster Guide",
		["Keep it: {npc:5875} in {zone:1454}, at the end of this guide"] = "Behalte sie: {npc:5875} in {zone:1454}, am Ende dieses Guides",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "Nach Norden zu {area:383}. {npc:3682} lagert unterhalb der Hügel; {npc:261366}, der Einsiedler auf dem Kamm hinter ihm, hat erst Arbeit für dich, wenn {npc:3682} dich hinaufschickt.",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last {area:380} stop."] = "Auf dem Weg die {area:458} zurück hinunter zum {area:378}: Die Räuber der Grimmhauer zwischen den Lagern der Borstennacken, zu beiden Seiten der Straße nördlich des Lagers, tragen {item:277277}. Gib sie bei deinem letzten Halt in {area:380} an {npc:3432}.",
		["Pickpocket {npc:7287} for the tower key before opening the lockbox. Gallywix and his lockbox are at the top; the key does not open that box, which still needs Lockpicking. Gallywix is elite: grouping up is advised. If you postpone this optional job, resume it in the Class guide Poisons (Horde)."] = "Stiehl {npc:7287} den Turmschlüssel, bevor du die Kiste öffnest. Gallywix und seine Kiste sind ganz oben; der Schlüssel öffnet diese Kiste nicht, sie braucht weiter Schlossknacken. Gallywix ist Elite: Eine Gruppe wird empfohlen. Schiebst du diesen optionalen Auftrag auf, setze ihn im Klassen-Guide Gifte (Horde) fort.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "Tauren: {npc:11957} wartet auf dem südlichen Hügel über der Brücke. Himmelsgeborene: {npc:272054} steht südlich der Zwillingsbrücken. Dann die Grabhügel östlich des Sees: Verlass deine Gestalt, klick die Statue am Eingang an für fünf Minuten Verstohlenheit, halte dich von den Geistern darin fern und nimm von jedem Relikt eins; {item:280680} liegt am Fuß der weißen Katzenstatue.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Die Vorarbeiter und Vollstrecker der Venture Co. an der Mine in der Nordostecke des Gebiets lassen {item:5097} fallen.",
		["The dwarves' flying machine sits on its platform inside the dig site."] = "Die Flugmaschine der Zwerge steht auf ihrer Plattform in der Grabungsstätte.",
		["The flying machine"] = "Die Flugmaschine",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960} ist die Schlucht unter dem {object:172982}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792} liegt am Nordrand von {area:382}, beim Turm der Venture Co. Darin ist {item:15883} für {quest:30}.",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "Donnerfalkenwolkenkitzler kreisen über denselben Ebenen südlich des Lagers.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "Donnerköpfe grasen auf den Ebenen gleich südlich vom {area:378}. {quest:884}, eine blaue Donnerechse, streift zwischen ihnen umher: Ihr Schwanzstachel startet eine Quest.",
		["Twitching Antennae"] = "Zuckende Fühler",
		["Twitching Antennae from the silithid"] = "Zuckende Fühler von den Silithiden",
		["Venture Co. tower"] = "Turm der Venture Co.",
		["{item:10338}, from any zhevra; Zhevra Chargers graze around the tree"] = "{item:10338}, von jedem Zhevra; Zhevra-Stürmer grasen rund um den Baum",
		["{item:15852}: Lost Barrens Kodos on the plains around the Kolkar camp"] = "{item:15852}: Verirrte Brachlandkodos auf den Ebenen um das Lager der Kolkar",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: Benutze eine Hälfte beim {area:2362}",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} von {npc:3490}; Kräuterkundige pflücken es auf den Ebenen",
		["{item:2449}: herbalists pick it here"] = "{item:2449}: Kräuterkundige pflücken es hier",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798} in {area:2361} fliegt Druiden dorthin",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: der Willkommensgruß von {npc:3033}",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the {area:380}"] = "{npc:12296}: Benutze {item:15826} an ihnen; sie streifen überall um {area:380} über die Ebenen",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, oben im Baum gleich östlich von {npc:3341}",
		["{npc:246344} teaches Paladins in {area:1638}. You have no flight path there yet: fly to {area:378}, head west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "{npc:246344} lehrt Paladine in {area:1638}. Du hast dort noch keinen Flugpunkt: Flieg nach {area:378}, geh nach Westen durch {zone:1412} und einen Aufzug hinauf und nimm den Flugpunkt bei {npc:2995} auf der mittleren Anhöhe.",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal."] = "{npc:262119} und seine Marinesoldaten halten die zerstörte Karawane südlich von {npc:261366}. Die Marinesoldaten sind verbunden: Pullst du einen, rufst du den Rest. Zieh vom Rand und lauf; sie lassen schnell ab, sodass du das Lager einzeln ausdünnen kannst, bevor du den Korporal angehst.",
		["{npc:3341} waits in a small camp further south, on the road toward {area:359}."] = "{npc:3341} wartet in einem kleinen Lager weiter südlich, an der Straße Richtung {area:359}.",
		["{npc:3389} stands at the Kolkar watch post just west of the {area:380}."] = "{npc:3389} steht am Wachposten der Kolkar gleich westlich von {area:380}.",
		["{npc:3394} stands in the Kolkar camp north-west of {npc:3389}."] = "{npc:3394} steht im Lager der Kolkar nordwestlich von {npc:3389}.",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the {area:380}."] = "{npc:3395} läuft zwischen den Kolkar an {area:388} südöstlich von {area:380} herum.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. Hand his head to {npc:3389} on your last {area:380} stop."] = "{npc:3396} führt die Kolkar am Westufer von {area:387} an, südlich von {npc:3389}. Gib seinen Kopf bei deinem letzten Halt in {area:380} an {npc:3389}.",
		["{npc:3428}: the eggs are in the {area:390}, later"] = "{npc:3428}: Die Eier sind im {area:390}, später",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, oben auf dem Turm",
		["{npc:3429}. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}. Behalte sie: Kadrak am {area:1703}, nächster Guide",
		["{npc:3430}, in the cage"] = "{npc:3430}, im Käfig",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} bietet {quest:95774} an, sobald {quest:4921} abgegeben ist",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, am Nordrand des Lagers",
		["{npc:3442}, beside the wind rider master. Keep it: {quest:1483} is in Stonetalon, later"] = "{npc:3442}, neben dem Windreitermeister. Behalte sie: {quest:1483} ist im Steinkrallengebirge, später",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} ist in der Feste angekettet. Sprich mit ihm, um die Eskorte zu starten, und bleib dicht dran: Soldaten von Theramore greifen auf dem Weg hinaus an. Er führt dich zurück nach {area:392}.",
		["{npc:5878} camps beside the road east of the {area:380}."] = "{npc:5878} lagert an der Straße östlich von {area:380}.",
		["{npc:5899}, just west of {npc:3341}"] = "{npc:5899}, gleich westlich von {npc:3341}",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} wartet auf dem Hügel südlich von {area:392}, auf deinem Weg nach Norden.",
		["{npc:5909}, a few steps away"] = "{npc:5909}, ein paar Schritte entfernt",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} steht im {object:172961}, auf der Westseite der Stadt.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: {npc:4606} in {zone:1458}, zwei Guides weiter",
		["{object:3972} poster"] = "Plakat „{object:3972}“",
		["{quest:2458}: {npc:7233}, by the {area:382}"] = "{quest:2458}: {npc:7233}, bei {area:382}",
		["{quest:865}, if still open: Sunscale Scytheclaws prowl among the lions"] = "{quest:865}, falls noch offen: Bluthornsensenklauen streifen zwischen den Löwen umher",
		["{quest:882}, a big Sunscale raptor, only comes to a fresh kill: loot a {item:10338} from a zhevra, then use it at the {object:147538} north-west of {area:392}, north of the road to the {area:380}, and be ready when he arrives."] = "{quest:882}, ein großer Raptor der Sonnenschuppen, kommt nur zu einem frischen Kill: Plündere {item:10338} von einem Zhevra und benutze ihn am toten Baum nordwestlich von {area:392}, nördlich der Straße zum {area:380}, und sei bereit, wenn er kommt.",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "Zurück auf die Straße nach Süden. Wo sie nach Osten nach {area:287} abbiegt, wartet {npc:2214} am {area:285}.",
		["Back to {npc:8582}"] = "Zurück zu {npc:8582}",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Jeder Naga der Rächerflossen am Strand nördlich des Außenpostens lässt Köpfe fallen.",
		["Fly to {area:431} and head south down the road to the {area:1703}."] = "Flieg nach {area:431} und geh die Straße nach Süden hinunter zum {area:1703}.",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Folge der Straße nach Norden Richtung {area:467}. Gehörnte Renner grasen am Weg; die Blutsaftbestien, Mondlichtläufer und Siechdrachen streifen durch die Wälder unterhalb des Gipfels, und die Cenarischen Druiden halten den Hain dort.",
		["Follow the road west to {area:460}."] = "Folge der Straße nach Westen zum {area:460}.",
		["Gaea Dirt Mounds"] = "Gaeaerdhügel",
		["Gaea Seeds"] = "Gaeasamenkörner",
		["Head back down the {area:1076} to {area:2539}."] = "Geh den {area:1076} zurück hinunter nach {area:2539}.",
		["Keep north on the road. The {npc:12862} waits at the Warsong lumber camp, south of Splintertree."] = "Bleib auf der Straße nach Norden. {npc:12862} wartet im Holzfällerlager der Warsong, südlich von Splintertree.",
		["Naga heads"] = "Nagaköpfe",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "Auf dem Weg nach Westen steckt {npc:267214} in einer Schlucht südlich der Hauptstraße fest, südöstlich von {area:415}. Schattenhornhirsche und Ashenvalebären streifen rundherum durch die Wälder.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "Südwestlich vom Sonnenfels liegt das {area:465}. Pflanz die Gaeasamenkörner in die Erdhügel auf dem Talgrund; die Feuerelementare lassen {item:16312} fallen. Harpyien und Wegelagerinnen der Blutfurien nisten auf der Nordseite, Töterinnen und Wildfedern im Süden.",
		["Sputtervalve in {area:392}: the next guide passes there"] = "Sputtervalve in {area:392}: Der nächste Guide kommt dort vorbei",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Steuere {npc:267214}s {npc:271181} innerhalb von vier Minuten aus der Schlucht zur Hauptstraße; bricht die Kanalisierung ab, frag {npc:267214} erneut.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "Die Straße steigt als {area:1076} nach Norden an. {quest:1483} hat eine Hütte, wo die Straße nach Osten zum {area:461} abzweigt.",
		["The {npc:12864} patrols the road east of {area:428} toward the {area:430}."] = "{npc:12864} patrouilliert auf der Straße östlich von {area:428} Richtung {area:430}.",
		["Use the {npc:212753} at the {object:645153} for a willing sacrifice and kill the {npc:212753} that answers. {quest:95883} is elite: grouping up is advised."] = "Benutze {npc:212753} an {object:645153} für ein freiwilliges Opfer und töte {npc:212753}, die antwortet. {quest:95883} ist Elite: Such dir am besten eine Gruppe.",
		["{area:431} is just north up the road."] = "{area:431} liegt gleich nördlich die Straße hinauf.",
		["{item:16746}, from the {item:16783}"] = "{item:16746}, aus dem {item:16783}",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, von einem {npc:1973}",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, von jeder Harpyie der Blutfurien",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: Glitzernde Sonnensteine von den Harpyien der Blutfurien",
		["{npc:11860}: Grish is at the {area:1718}, in the next guide"] = "{npc:11860}: Grish ist am {area:1718}, im nächsten Guide",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, neben {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, oben auf dem Felsvorsprung",
		["{npc:12736} at Zoram'gar, at 27"] = "{npc:12736} in Zoram'gar, mit 27",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Darthalia in {area:272}",
		["{npc:271181}, on the road"] = "{npc:271181}, auf der Straße",
		["{npc:4198}, outside the gate"] = "{npc:4198}, vor dem Tor",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "Hast du „Mission: Possible But Not Probable“ bei Shenthul abgegeben, bring {quest:2479} zu {npc:2391} in {area:272}. Bleib neben ihm, bis das Brauziel abgeschlossen ist, und gib dann die Folgequest ab, um Gifte zu lernen. Schließe sie auch dann ab, wenn das Zanzilgift schon entfernt wurde; das Entfernen des Debuffs allein lehrt die Fertigkeit nicht.",
		["Bears, creepers and lions"] = "Bären, Krabbler und Löwen",
		["Drull's ball and chain"] = "Drulls Kugel und Kette",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Füll den {item:7768} am {object:107045} neben dem Gasthaus",
		["Follow the road south to the dwarf dig site at {area:359}. {npc:3421} hides at the south edge of the dig; {object:3646} sits at the bottom of the excavation."] = "Folge der Straße nach Süden zur Ausgrabungsstätte der Zwerge bei {area:359}. {npc:3421} versteckt sich am Südrand der Grabung; {object:3646} steht ganz unten in der Ausgrabung.",
		["From {zone:1454} (zeppelin from the towers outside the {zone:1458}) fly to {area:378}."] = "Flieg von {zone:1454} (Zeppelin von den Türmen vor {zone:1458}) nach {area:378}.",
		["Keep it: the {area:287} coast, later on the route"] = "Behalte es: die Küste von {area:287}, später auf der Route",
		["Masoj hides on the hillside above {area:290}, south of Durnholde, on the way down to the blossoms."] = "Masoj versteckt sich am Hang über {area:290}, südlich von Burg Durnholde, auf dem Weg hinunter zu den Blüten.",
		["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "Giftreihe unvollendet? Setze deine aktuelle Stufe im Klassen-Guide Gifte (Horde) fort; abgeschlossene Quests müssen nicht neu begonnen werden. Organisiere eine Gruppe für Gallywix, schließe die Folgequest von Hinott ab und kehre dann zu diesem Leveling-Guide zurück.",
		["South-west of Durnholde, the {item:3502} grow on the hillsides above the river."] = "Südwestlich von Burg Durnholde wachsen die {item:3502} an den Hängen über dem Fluss.",
		["Take the zeppelin from the towers outside the {zone:1458} to {zone:1454} and train before you fly on."] = "Nimm den Zeppelin von den Türmen vor {zone:1458} nach {zone:1454} und trainiere, bevor du weiterfliegst.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "Die Höfe östlich des Orts {area:287}. {npc:232} bestellt das Feld beim nördlichen Bauernhaus, {npc:2403} das weiter südöstlich; Landarbeiter und Bauern von Hillsbrad sind überall. {npc:2451} pflegt das Feld südlich der Höfe.",
		["The smithy"] = "Die Schmiede",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "Die Schmiede steht mitten im Ort {area:287}. {npc:2404} und seine Lehrlinge arbeiten an der Esse; die {object:1736} ist daneben gestapelt. {npc:2449} läuft die Straße nördlich davon entlang.",
		["The town hall is on the west side of {area:287}. {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "Das Rathaus liegt auf der Westseite von {area:287}. {npc:2335} (30) und {npc:2448} sind drinnen beim Stadtverzeichnis von Hillsbrad; die Proklamation von Hillsbrad hängt daneben. Ratsherren von Hillsbrad laufen durch den Ort.",
		["The {area:288} lies south of {area:287} town. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "Der Ort {area:288} liegt südlich des Orts {area:287}. Minenarbeiter von Hillsbrad arbeiten in den Stollen; {npc:2305} (30) und {npc:2450} (29) sind tief drinnen.",
		["Town hall"] = "Rathaus",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "Westlich von Tarrens Mühle streifen Graubären, Waldmooskrabbler und Verhungernde Berglöwen auf dem Weg hinunter zu den Höfen durch die Hügel. Die Krabbler droppen {item:3477} selten; du brauchst nur eins.",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272} ist dein Stützpunkt für diesen Guide: Der Ruhestein bringt dich zweimal hierher zurück. Alle stehen rund um den Dorfplatz.",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}: die Arbeiter auf den Feldern",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, im Apothekarium",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, in {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}: Befehle für {npc:270438}, auf dem Weg nach Burg Durnholde",
		["{npc:2238}'s ball and chain"] = "Kugel und Kette von {npc:2238}",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} ist der Hund von {npc:232}, beim nördlichen Bauernhaus im Gebiet {area:286}.",
		["{npc:2388}: the last guide binds here, so this usually ticks at once"] = "{npc:2388}: Der letzte Guide bindet dich hier, daher ist das meist sofort abgehakt",
		["{npc:2391}: Poisons"] = "{npc:2391}: Gifte",
		["{npc:3442}, by the docks in {area:392}"] = "{npc:3442}, bei den Docks in {area:392}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "Die Hütte von {npc:5899} steht auf dem Grat über dem Wasserloch der Stacheleber, südlich von {area:378}, auf dem Weg nach {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: Der blaue Wasserschlauch wird im {zone:1440} gefüllt, nächster Guide",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: der rote Wasserschlauch aus {area:272}",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, ein großer Dreschadon, schwimmt im seichten Wasser vor der Küste ({area:391}), östlich von {npc:3388} Skyseer.",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "Zurück nach Süden zum Lager, dann hinauf nach {zone:1456} für den Flug nach {area:378}.",
		["Back south-west to {area:421}. Befouled Water Elementals drift around its shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Zurück nach Südwesten zum {area:421}. Beschmutzte Wasserelementare treiben an seinen Ufern; der Pavillon steht auf der Insel mit Blick auf den Außenposten der Allianz.",
		["Back west to Zoram'gar before heading east for good."] = "Zurück nach Westen nach Zoram'gar, bevor es endgültig nach Osten geht.",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Steig den Pfad hinauf auf den {area:2097}. {npc:10646} wird neben {npc:10896} (29) gefangen gehalten: Besiege zuerst die Wachen und {npc:10896}, befreie sie dann und beschütze sie auf dem Weg hinunter; unterwegs greifen dich Grimmtotem aus dem Hinterhalt an.",
		["Felmusk satyrs"] = "Satyrn der Teufelshufe",
		["Follow the canyon east out of the mesas onto the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Folge der Schlucht nach Osten aus den Tafelbergen hinaus auf die Salzebenen. Die Goblins und Gnome der {area:2240} sind neutral und geben beiden Fraktionen Quests.",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Folge der Hauptstraße nach Osten an {area:415} vorbei (Allianz: bleib auf der Straße). {npc:12678}, ein großer Grizzly, streift durch die Ruinen ({area:418}) südlich der Straße, westlich von {area:421}. Seine Pranke startet die nächste Jagdquest.",
		["Galak centaurs"] = "Zentauren der Galak",
		["Gazebo"] = "Pavillon",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Toxinproben der Düsteranhöhe, von den Angenagten Leichnamen",
		["His crate is for Stranglethorn, later on the route"] = "Seine Kiste ist fürs Schlingendorntal, später auf der Route",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Bleib auf der Straße nach Osten. {npc:12858} wartet südwestlich vom Holzfällerlager der Warsong. Er und seine Grunzer stürmen den {area:2360}: Lass sie die Aggro ziehen und bleib bei {npc:12858}, bis {npc:12860} tot ist.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Töte den {npc:10720}, der für {npc:10638} kommt",
		["Naga brazier"] = "Nagakohlenpfanne",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "Nördlich des Lagers überrennen Spinnen die Grabstätte {area:17044}. Benutze den {item:273015} von {npc:264074} an den Angenagten Leichnamen; die Spinner lassen {item:273181} fallen. {npc:264082} sitzt am Nordende: Ihr {item:273658} startet {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "Nordwestlich vom Splintertreeposten lagern die Satyrn der Teufelshufe im Wald. Jeder Satyr kann Hörner fallen lassen.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Fahr mit dem Aufzug hinunter und folge dann der Straße nach Osten durch die Schluchten zum {area:484}, einem Taurendorf oben auf den Tafelbergen. Sein Aufzug ist auf der Nordseite.",
		["Sapphires of Aku'Mai"] = "Saphire von Aku'Mai",
		["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s."] = "Südlich vom Düsterwolkengipfel: die Harpyien im {area:487}. {npc:4490} (31) läuft zwischen ihnen umher: Dünn die Harpyien um sie aus, bevor du sie pullst. Die Kreischenden Harpyien, Wildfedern und Windruferinnen dort sind für {npc:4877}.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Sprich mit {npc:3057} in {area:1638}: {quest:93739}",
		["Take a lift down from {zone:1456}. The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}."] = "Fahr mit einem Aufzug von {zone:1456} hinunter. Das Lager des Irdenen Rings steht nördlich der Klippen: {npc:264074}, {npc:264072} und {npc:259118}.",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Fahr mit dem Aufzug hinunter. Das Ei liegt in einem Nest am Schluchtboden an einer von drei Stellen: südöstlich der Tafelberge (52.3,55.2), östlich (56.4,50.4) oder südwestlich (37.6,56.1).",
		["Talk to {npc:3057}"] = "Sprich mit {npc:3057}",
		["The Earthen Ring"] = "Der Irdene Ring",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Die Furbolgs der Fäulnisklauen halten die Wälder östlich von {area:421}, südlich der Straße. Stell {item:16972} auf den {object:178206} und bewache es: Die Furbolgs kommen, um es niederzureißen. {npc:12918} kommt zuletzt; sein Totem fällt in den Korb.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "Die Lager der Galak füllen die Schlucht nördlich vom Freiwindposten; Späher, Zänker und Windhetzerinnen der Galak teilen sich jedes Lager. Ein einzelner {npc:10617} läuft zwischen den Lagern: Töte ihn, wenn du ihn triffst, seine Notiz startet eine Quest für den {area:2237}.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "Die Saphire sind blaue Kristalle an den Wänden der Tunnel zum Portal der {area:2797}, unterirdisch und außerhalb der Instanz: Schwimm aus der Grube hinab, unter der Mauer hindurch, in die Höhle. Die Satyrn und Naga in den Tunneln sind Elite: Eine Gruppe wird empfohlen. Die Kristalle erscheinen schnell wieder, du musst also nicht tief hinein.",
		["The Wanted poster beside {npc:10537}"] = "Der Steckbrief neben {npc:10537}",
		["The fountain stands in the middle of the {area:418}: use the {item:7767} there."] = "Der Brunnen steht mitten in den Ruinen ({area:418}): Benutze dort den {item:7767}.",
		["The next guide flies on from here to {zone:1454}."] = "Der nächste Guide fliegt von hier weiter nach {zone:1454}.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "Der Weg zu den Saphiren führt durch die versunkenen Ruinen am Nordende des Strands: Geh die Treppe hinunter in die Grube.",
		["Thistlefur Hold"] = "Höhle der Distelfelle",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "Westlich vom Freiwindposten liegen die Lager der Grimmtotem unterhalb vom {area:2097}. Die Geheimnotizen liegen in Dokumententruhen im südöstlichen, südwestlichen und nordwestlichen Lager.",
		["for {npc:5901}, south of {area:392}: next guide"] = "für {npc:5901}, südlich von {area:392}: nächster Guide",
		["{area:2797} ruins"] = "Ruinen: {area:2797}",
		["{area:418} fountain"] = "Brunnen: {area:418}",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, von Spinnern der Düsteranhöhe",
		["{item:273658}, from {npc:264082}"] = "{item:273658}, von {npc:264082}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, beim Windreitermeister",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "{npc:10428}s nächste Quest, Hochheiliges Feuer, endet in {zone:1456}, abseits dieser Route. Überspring sie.",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp. Her claw starts the next hunt quest."] = "{npc:12676}, ein großer Nachtsäbler, streift durch die Wälder südöstlich vom Holzfällerlager der Warsong. Ihre Klaue startet die nächste Jagdquest.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, ein Schattenpanther, pirscht durch die Wälder um {area:426}, westlich vom Lager der Teufelshufe. Ihr Kopf startet die nächste Jagdquest.",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead."] = "{npc:12717} geht den Strand hinauf nach Norden zu einer Nagakohlenpfanne. Lösch die Kohlenpfanne und beschütze ihn dann durch die Wellen der Naga, bis Vorsha die Peitscherin tot ist.",
		["{npc:12717}: starts his escort at once"] = "{npc:12717}: Seine Eskorte beginnt sofort",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: nur, wenn du die Handbuchseiten dabeihast",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} bietet als Nächstes eine Quest für die {area:2797} an; lass sie aus, außer du hast eine Gruppe.",
		["{npc:12759}, a corrupted water elemental, drifts in {area:421}. Her {item:16408} starts a quest for Splintertree."] = "{npc:12759}, ein verderbter Wasserelementar, treibt im {area:421}. Ihr {item:16408} startet eine Quest für den Splintertreeposten.",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, eine Ergänzung von Forever, steht am Westufer von {area:421} mit drei schnellen Drachentöter-Quests.",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} steht oben auf einem Tafelberg östlich der Lager der Galak. Für {quest:1149} geh über das Ende der Planken neben ihm hinaus: Du landest sicher.",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, around level 38"] = "{npc:4454}: Sein Brief geht an Martek im {zone:1418}, etwa auf Stufe 38",
		["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}. {npc:4499} is elite: grouping up is advised."] = "{npc:4499}, ein hart zuschlagender Felselementar, wandert über die Klippen ({area:482}). {npc:4499} ist Elite: Eine Gruppe wird empfohlen.",
		["{object:176344}, north-west camp"] = "{object:176344}, nordwestliches Lager",
		["{object:176344}, south-east camp"] = "{object:176344}, südöstliches Lager",
		["{object:176344}, south-west camp"] = "{object:176344}, südwestliches Lager",
} end)()
t.guides["forever/horde/30-40/01-desolace"] = (function() return {
		["Back to {area:272}"] = "Zurück nach {area:272}",
		["Clam beds"] = "Muschelbänke",
		["Daggerspine naga"] = "Naga der Säbelflossen",
		["Daggerspine shore"] = "Ufer der Säbelflossen",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:392}. {npc:5901} camps on the coast a short walk south of the town."] = "Flieg nach {area:392}. {npc:5901} lagert an der Küste, einen kurzen Fußweg südlich der Stadt.",
		["Fly to {area:460}"] = "Flieg nach {area:460}",
		["Fly to {area:484}. {npc:5905} hides in a small cave in the canyon wall north-east of the post."] = "Flieg zum {area:484}. {npc:5905} versteckt sich in einer kleinen Höhle in der Schluchtwand nordöstlich des Postens.",
		["Follow the road north out of {area:272} into the Alterac foothills. {quest:535} waits by the Syndicate camp; hand him the stout."] = "Folge der Straße nach Norden aus {area:272} hinaus in die Ausläufer des Alteracgebirges. {quest:535} wartet beim Lager des Syndikats; gib ihm das Starkbier.",
		["Follow the shore west past {area:271}'s bay; the Torn Fin murlocs camp on the beaches beyond it."] = "Folge dem Ufer nach Westen an der Bucht von {area:271} vorbei; die Murlocs der Fetzenflossen lagern an den Stränden dahinter.",
		["Head back east to {area:272}."] = "Geh zurück nach Osten zu {area:272}.",
		["Head back north to {area:272}, keeping west of {area:271}."] = "Geh zurück nach Norden zu {area:272} und halte dich westlich von {area:271}.",
		["Head back south to the post."] = "Geh zurück nach Süden zum Posten.",
		["Head back south to {area:272}."] = "Geh zurück nach Süden zu {area:272}.",
		["Head north up the coast. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach; open each clam in your bags for its meat."] = "Geh die Küste nach Norden hinauf. Riesen-Weichpanzermuscheln liegen im Flachwasser, und die Wütenden Riffkriecher laufen am Strand; öffne jede Muschel in deinen Taschen für ihr Fleisch.",
		["Head north-east to {area:609}. {quest:1365} (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health."] = "Geh nach Nordosten zum {area:609}. {quest:1365} (35) geht auf der Ostseite zwischen den Zelten mit ein oder zwei Schlachtfürsten (32-33) umher: Räume um ihn herum auf und zieh ihn dann allein bei voller Gesundheit.",
		["Head south, east of {area:271}, down to the coast. The Daggerspine naga line the shore south-east of the town."] = "Geh nach Süden, östlich von {area:271}, hinunter zur Küste. Die Dolchrückennaga säumen das Ufer südöstlich der Stadt.",
		["Head south-east to the post."] = "Geh nach Südosten zum Posten.",
		["Head south-west to the troll village on the coast, keeping clear of the {area:606} on the way."] = "Geh nach Südwesten zum Trolldorf an der Küste und halte dich dabei vom {area:606} fern.",
		["Head west to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. They also drop a {item:20310} now and then (1-5%); if one drops, read it."] = "Geh nach Westen zur {area:599}. Prügle einen Kultisten der Brennenden Klinge nieder und benutze dann {item:6436} an ihm, bevor er stirbt, um einen {item:6435} zu füllen. Sie lassen auch ab und zu {item:20310} fallen (1-5 %); fällt einer, lies ihn.",
		["Keep north to {area:598}. The Oracles stand among the other naga at its north end; pull one at a time."] = "Weiter nach Norden zum {area:598}. Die Orakel stehen zwischen den anderen Naga an seinem Nordende; pull sie einzeln.",
		["Kolkar ears"] = "Kolkarohren",
		["Shadowstalker scalp"] = "Skalp eines Schattenpirschers",
		["Shindigger keg"] = "Fässchen Shindigger-Starkbier",
		["Slitherblade Oracles"] = "Orakel der Zackenkämme",
		["South-west, the Cave and Ferocious Yetis (30-31) fill the caves in the hills west of {area:272}; about one in sixteen carries the rod."] = "Im Südwesten füllen Höhlenyetis und Wilde Yetis (30-31) die Höhlen in den Hügeln westlich von {area:272}; etwa jeder sechzehnte trägt die Rute.",
		["Syndicate missives"] = "Schreiben des Syndikats",
		["Thaivand's next task ends at {area:271}'s graveyard and the magus offers a dungeon errand: leave both."] = "Thaivands nächste Aufgabe endet auf dem Friedhof von {area:271}, und der Magus bietet einen Dungeonauftrag an: Lass beide aus.",
		["The Hatefury Shadowstalkers at {area:603} walk unseen until they strike; about one in three carries a scalp."] = "Die Schattenpirscher der Zornsäer in {area:603} sind unsichtbar, bis sie zuschlagen; etwa jeder dritte trägt einen Skalp.",
		["The Syndicate Footpads and Thieves (32-33) around the camps west of the road carry the missives; about one in three drops one."] = "Die Schleicher und Diebe des Syndikats (32-33) um die Lager westlich der Straße tragen die Schreiben; etwa jeder dritte lässt eins fallen.",
		["The keg stands with a few others at the Syndicate camp on the south-east coast of {area:287}."] = "Das Fässchen steht mit einigen anderen im Lager des Syndikats an der Südostküste von {area:287}.",
		["The {area:279} traitors"] = "Die Verräter von {area:279}",
		["Torn Fin beach"] = "Strand der Fetzenflossen",
		["Torn Fin murlocs"] = "Murlocs der Fetzenflossen",
		["Train"] = "Trainieren",
		["Train your new spells."] = "Lerne deine neuen Zauber.",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. Five kodos, one at a time."] = "Benutze {npc:11596}s {item:13892} an einem Gealterten, Sterbenden oder {npc:4702} auf dem Friedhof und führe den gezähmten Kodo zurück zu {npc:11596}. Fünf Kodos, einer nach dem anderen.",
		["for {npc:5901}: from Stranglethorn, next guide"] = "für {npc:5901}: aus dem Schlingendorntal, nächster Guide",
		["{area:2408} flight master"] = "Flugmeister: {area:2408}",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}: Auktionshaus oder ein Alchemist, für {quest:515}.",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, für {npc:2333}",
		["{npc:11863} waits in the ruined tower of {area:2405}, inland to the south-east."] = "{npc:11863} wartet im verfallenen Turm von {area:2405}, landeinwärts im Südosten.",
		["{npc:11877}: for {npc:715} in Stranglethorn"] = "{npc:11877}: für {npc:715} im Schlingendorntal",
		["{npc:2229}: for the {zone:1413}, later on the route"] = "{npc:2229}: fürs {zone:1413}, später auf der Route",
		["{npc:2770}: for {area:321} in Arathi, later on the route"] = "{npc:2770}: für {area:321} im Arathihochland, später auf der Route",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Grommash Hold, falls du sie dabeihast",
		["{npc:5395} stands in the post; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395} steht im Posten; {npc:5641} und {npc:4498} warten auf der Anhöhe westlich davon, über dem Friedhof ({area:596}).",
		["{npc:5639} waits in the Drag; {npc:5640} stands in the {object:172961} on the west side of the city. Skyborne: {npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:5639} wartet in der Gasse; {npc:5640} steht im {object:172961} auf der Westseite der Stadt. Himmelsgeborene: {npc:4949} wartet in der Feste Grommash im {object:172957}.",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "{npc:5641}s nächster Auftrag schickt dich zu einem Dämonenfürsten mit Elitewache: Überspring ihn.",
		["{npc:5641}'s next {quest:1431} sends you back to {zone:1454} for nothing: leave it."] = "{npc:5641}s nächste Quest {quest:1431} schickt dich umsonst zurück nach {zone:1454}: Lass sie aus.",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} steht im {object:172957}.",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} startet auch Elementare Hilfe ({area:1717}), die Kette (33-40) zu The Tempest's Weapons: forever/class/shaman/call-of-air-horde.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: dein {item:5178}",
		["{quest:515} needs a {item:3388}, an {skill:171} item: buy one at the auction house here if you can (or ask an alchemist). No potion: skip the Elixir steps in {area:287}."] = "{quest:515} braucht einen {item:3388}, einen Gegenstand aus {skill:171}: Kauf einen hier im Auktionshaus, wenn du kannst (oder frag einen Alchemisten). Kein Trank: Überspring die Elixier-Schritte in {area:287}.",
		["{zone:1454} class quests"] = "Klassenquests in {zone:1454}",
} end)()
t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "Zurück nach Norden zum Lager.",
		["Back to {object:3202}."] = "Zurück nach {object:3202}.",
		["Elder tigers and Lashtail raptors"] = "Alte Tiger und Schmetterschwänze",
		["Fly to {area:35}"] = "Flieg nach {area:35}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "Folge der Straße von {object:3202} nach Norden; Nesingwarys Jagdlager liegt auf dem Hügel nordöstlich des Flusses. Ab hier behältst du jede Seite von {quest:338}, die du erbeutest: {npc:716} Stonepot will sie später.",
		["Follow the road south to {area:35} at the southern tip of the vale and enter through the tunnel in the cliffs. Stay on the road: the jungle beside it is well above your level. {npc:2858}, the Horde flight master, waits on the upper deck."] = "Folge der Straße nach Süden nach {area:35} an der Südspitze des Tals und geh durch den Tunnel in den Klippen hinein. Bleib auf der Straße: Der Dschungel daneben liegt weit über deiner Stufe. {npc:2858}, der Flugmeister der Horde, wartet auf dem oberen Deck.",
		["Follow the road south to {object:3202}."] = "Folge der Straße nach Süden nach {object:3202}.",
		["Green Hills pages"] = "Seiten der Grünen Hügel",
		["Head north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "Geh nach Norden an Nesingwarys Lager vorbei zum See. Die Geologen der Venture Co. (34-36) arbeiten in den Lagern entlang seines Westufers; sie tragen die Gerommelten Kristalle.",
		["Head south down the coast to {object:3202} and fly to {area:35}."] = "Geh die Küste nach Süden hinunter nach Grom'gol und flieg nach {area:35}.",
		["Nesingwary's camp"] = "Lager von Nesingwary",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "Nordwestlich von Grom'gol liegt {area:104} unter Wasser vor der Küste. Die {item:4094} liegt auf dem Meeresgrund bei den versunkenen Ruinen; achte auf deinen Atem und die Murlocs.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "Seiten von {item:2755} droppen mit je etwa 1% von den Trollen der Bloodscalp und der Skullsplitter; behalte jede Seite, die du erbeutest, und schau im Auktionshaus nach dem Rest. {npc:716} Stonepot nimmt die Kapitel später in diesem Guide.",
		["Shadowmaw panthers"] = "Schattentatzenpanther",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "Schlingendorntiger und Panther (32-33) streifen durch die Hügel östlich des Lagers am Seeufer.",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "Die Schmetterschwänze (35-36) jagen im Dschungel gleich nordöstlich von {object:3202}.",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "Die Schattentatzenpanther (37-38) schleichen durch den Dschungel östlich der Hügel der Mosh'Ogg und nordöstlich Richtung See; sie greifen aus der Verstohlenheit an. Erbeute unterwegs jede Seite der Grünen Hügel.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "Die Schattentatzenpanther kommen viel später, bei {object:3202}",
		["The camp by the river"] = "Das Lager am Fluss",
		["The zeppelin lands at the tower on the west side of the camp."] = "Der Zeppelin landet am Turm auf der Westseite des Lagers.",
		["Venture Co. camp"] = "Lager der Venture Co.",
		["Zeppelin to {object:3202}"] = "Zeppelin nach {object:3202}",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: für das Arathihochland, später auf der Route",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} und dein {item:5177}",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "Das Lager der vermissten Jäger von {npc:773} ist das von Nesingwary: Geh zwischen den Zelten umher, dann ist die Untersuchung abgeschlossen. Flusskrokilisken liegen am Fluss unterhalb des Lagers.",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Back to {area:321}"] = "Zurück nach {area:321}",
		["Boulderfist camp"] = "Lager der Felsfäuste",
		["Fleshstalker raptors"] = "Hochlandfleischpirscher",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Head back south down the road, past the {area:1877}."] = "Geh die Straße zurück nach Süden, am {area:1877} vorbei.",
		["Head east out of {area:272} through {area:1857} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south-east of {area:313}."] = "Geh von {area:272} nach Osten durch {area:1857} und folge der Straße nach Osten. Die Oger und Vollstrecker der Felsfäuste (32-34) lagern südlich der Straße, südöstlich von {area:313}.",
		["Head north up the road from the {area:380} to the {area:386}; {npc:3389} keeps watch on the rise above the water."] = "Geh die Straße vom {area:380} nach Norden zu den {area:386}; {npc:3389} hält auf der Anhöhe über dem Wasser Wache.",
		["Head north; the outer circle stands in the middle of the highlands."] = "Geh nach Norden; der äußere Kreis steht mitten im Hochland.",
		["Head south-west out of Arathi over {area:880}, south through the {zone:1437} (keep clear of {area:150}) and east into {zone:1432}; the road leaves {zone:1432} to the south into the {zone:1418}. Follow it south to the goblin camp in the {area:1877}."] = "Geh von Arathi nach Südwesten über {area:880}, südlich durch die {zone:1437} (halte dich von {area:150} fern) und östlich nach {zone:1432}; die Straße verlässt {zone:1432} nach Süden in die {zone:1418}. Folge ihr nach Süden zum Goblinlager im {area:1877}.",
		["Head south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Geh nach Südwesten zur Goblinbucht an der Südküste. {npc:2766} hält auf der Klippe darüber Wache.",
		["Head west along the road; {npc:2921}'s camp sits in the {area:1878} halfway to {area:340}."] = "Geh entlang der Straße nach Westen; das Lager von {npc:2921} liegt in der {area:1878}, auf halbem Weg nach {area:340}.",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Hochlandfleischpirscher (36-37) jagen im südlichen Hochland, ein Rudel nördlich von {area:316} und ein weiteres auf der Ebene westlich davon. Zieh sie einzeln.",
		["Highland Striders roam the hills all around {area:321}; both they and the Thrashers further west drop the eyes."] = "Hochlandschreiter streifen überall um {area:321} durch die Hügel; sie und die Hochlandhauer weiter westlich lassen die Augen fallen.",
		["Highland raptors"] = "Hochlandraptoren",
		["Into the {zone:1418}"] = "Ins {zone:1418}",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "Bleib auf der Straße nach Norden; die Truhe liegt in der Grabungsstätte von {area:1517}, am Fuß der Ruinen nordwestlich der Straße.",
		["Lesser Rock Elementals"] = "Kleine Felselementare",
		["The Boulderfist Brutes camp outside the ogres' hall south of {area:321}; the Magus stand among them. Pull them one at a time."] = "Die Schläger der Felsfäuste lagern vor der Halle der Oger südlich von {area:321}; die Magier der Felsfäuste stehen zwischen ihnen. Zieh sie einzeln.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "Der innere Kreis liegt südlich des westlichen Kreises, östlich von Stromgarde.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "Die Orcfestung am östlichen Ende der Straße. {npc:2851}, die Windreitermeisterin, steht beim Tor.",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "Die kleinen Elementare treiben über die Ebene gleich westlich von {npc:2921}s Lager. Jedes Felselementar im Gebiet kann {npc:6868}s Felselementarsplitter fallen lassen: Behalte sie.",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "Die nächste Aufgabe des Steins erfordert Fozruk, einen Elite der Stufe 42: Lass sie liegen.",
		["The violet shards glow just off the road a short way west of {area:321}."] = "Die violetten Splitter leuchten gleich neben der Straße, ein kurzes Stück westlich von {area:321}.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701} liegen am hinteren Ende der Schlucht.",
		["The {object:2702}"] = "{object:2702}",
		["Theldurin sits among the dwarven ruins at {area:345}, south of the {area:1877}."] = "Theldurin sitzt zwischen den Zwergenruinen an der {area:345}, südlich vom {area:1877}.",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Trainiere, solange du in {zone:1458} bist: Die Lehrer stehen im {object:36070}, im {object:36073} und im {object:36082} (Paladine: {npc:260093}).",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "Westlich der Bucht halten die Räuber und Zauberhexerinnen der Säbelflossen (38-40) das Ufer: Zieh sie einzeln. Die beiden Wracks liegen davor im seichten Wasser, die Karten und Logbücher darin; die Edelsteine liegen um die Wracks auf dem Meeresgrund.",
		["Your trainer is in {area:1638}, one flight from {zone:1454}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins). Fly on to the {area:380} from there."] = "Dein Lehrer ist in {area:1638}, einen Flug von {zone:1454} entfernt: {npc:3033} (Druiden) auf der {area:1639}, {npc:246344} (Paladine). Flieg von dort weiter nach {area:380}.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["for Helgrum in {area:75}, around level 42"] = "für Helgrum in {area:75}, etwa ab Stufe 42",
		["for {npc:2487} in {area:35}, around level 44"] = "für {npc:2487} in {area:35}, etwa ab Stufe 44",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "{quest:678} von {npc:2771} geht als Nächstes gegen Elite-Felsfäuste: Lass sie liegen.",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}: nur wenn du {item:2868} dabeihast ({skill:164} oder Auktionshaus)",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661} hat keinen Jäger- oder Schamanenlehrer: Nimm stattdessen vom selben Turm den Zeppelin nach {zone:1454} und trainiere in der Stadt, dann nimm vom Turm vor dem Haupttor von {zone:1454} den Zeppelin nach {zone:1458}.",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: Fizzles Brief aus {area:439}",
		["{zone:1458} trainers"] = "Lehrer in {zone:1458}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Fly to {area:378}"] = "Flieg nach {area:378}",
		["For {npc:2519} at {object:3202}, in the next guide"] = "Für {npc:2519} in {object:3202}, im nächsten Guide",
		["Head back west to Brackenwall with the head."] = "Geh mit dem Kopf zurück nach Westen nach Brackenwall.",
		["Head east back to the {area:497}."] = "Geh nach Osten zurück zum {area:497}.",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Geh von {area:378} entlang der Straße nach Osten in den Sumpf. Das ausgebrannte {area:403} steht direkt hinter der Grenze neben ihr; der Schild, das Abzeichen und die Hufspuren sind in und neben der Ruine.",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Geh nach Norden zum {area:502}. Stinki steht am Fuß des Hügels; eskortiere ihn, während er Sumpfbohnenblätter direkt südlich davon sammelt.",
		["Head north to {npc:5412} at {area:597}."] = "Geh nach Norden zu {npc:5412} bei {area:597}.",
		["Head north up the road to the hut by the road north of the graveyard."] = "Geh die Straße nach Norden zur Hütte an der Straße nördlich des Friedhofs.",
		["Head on south-west to Shadowprey."] = "Geh weiter nach Südwesten zur Schattenbeute.",
		["Head south from {area:2405} into the {area:607}. The Maraudine Scouts, Wranglers, Maulers, Windchasers and Marauders (36-39) drop the {quest:93225}."] = "Geh von {area:2405} nach Süden ins {area:607}. Die Späher, Treiber, Zermalmer, Windjäger und Marodeure der Maraudine (36-39) lassen {quest:93225} fallen.",
		["Head south-east from the coven to the bone fields of the {area:2657}, where Undead Ravagers roam. At the far south-east, use the {item:15848} to draw the Magrami Spectres: they drop the ghost-o-plasm."] = "Geh vom Hexenzirkel nach Südosten zu den Knochenfeldern des {area:2657}, wo Untote Verheerer umherstreifen. Benutze ganz im Südosten {item:15848}, um die Schreckgespenster der Magram anzulocken: Sie lassen das Geisterplasma fallen.",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Jarl wohnt im {area:497} südöstlich vom {area:502}.",
		["Kodo bones"] = "Kodoknochen",
		["Maraudine totems"] = "Totems der Maraudine",
		["Mirefin murlocs"] = "Murlocs der Schlammflossen",
		["Pick up the kodo bones scattered across the graveyard."] = "Sammle die über den Friedhof verstreuten Kodoknochen ein.",
		["Slitherblade coast"] = "Küste der Zackenkämme",
		["Stinky Ignatz"] = "Stinki Ignatz",
		["Swamp Eye Jarl"] = "Sumpfauge Jarl",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "Nimm an der Gabelung die Straße nach Norden zum Ogerdorf Brackenwall.",
		["The Burning Blade hold the fortress north-west of {area:2407}. Use the {item:14523} on the {npc:11876} in the fortress to get the {item:13542}."] = "Die Burning Blade hält die Festung nordwestlich von {area:2407}. Benutze {item:14523} an {npc:11876} in der Festung, um {item:13542} zu bekommen.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Die Murlocs der Schlammflossen drängen sich an der Küste östlich und nordöstlich vom {area:502}; jede Art lässt Köpfe fallen.",
		["The Slitherblade naga hold the coast north of {area:2405}, up to {area:598}. {npc:12369} guards the {quest:6027} at the far northern tip."] = "Die Naga der Zackenkämme halten die Küste nördlich von {area:2405} bis zum {area:598}. {npc:12369} bewacht {quest:6027} an der äußersten Nordspitze.",
		["The next guide takes you back to {zone:1434}."] = "Der nächste Guide bringt dich zurück ins {zone:1434}.",
		["The {area:2657}"] = "Das {area:2657}",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "nur, wenn du ein {item:3853} dabeihast ({skill:164} oder Auktionshaus)",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, am Südrand des Dorfs, wo die Straße hereinkommt",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983} wartet im Morast ({area:2302}) östlich des Dorfs. Folge ihm zu Reethe und halte ihn im ausbrechenden Kampf am Leben.",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} wartet im Goblinlager auf der Westseite des Friedhofs ({area:596}).",
		["{object:20985}, beside the manor"] = "{object:20985}, neben dem Anwesen",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, jetzt wo {npc:4791} den Bericht gelesen hat",
		["{quest:1218}, for \"Swamp Eye\" Jarl"] = "{quest:1218}, für „Sumpfauge“ Jarl",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Boat to {area:35}"] = "Schiff nach {area:35}",
		["Draenethyst crystals"] = "Draenethystkristalle",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Folge der Küste nach Süden. Die Forscher der Naga waten am Ufer entlang und tragen die Schilfbündel; {object:759} sprudelt in den Hügeln gleich östlich davon.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Gib Unbagwa die Fangzähne und bleib bei ihm: Er ruft drei Wellen Gorillas, dann {npc:1514}. Kämpf einzeln gegen sie.",
		["His strongbox waits at his old camp north of {area:75}."] = "Seine Geldkassette wartet in seinem alten Lager nördlich von {area:75}.",
		["Jungle stalkers"] = "Dschungelpirscher",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Verlass den Ort durch den Tunnel; die Notiz liegt in der Piratenbucht gleich nördlich von {area:35}.",
		["Mistvale gorillas"] = "Nebeltalgorillas",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Noboru wandert über die Lichtung südwestlich vom {area:76}; sein Knüppel startet eine Quest.",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "Nordöstlich des Nebeltals lagern Zanzils Anhänger im Dschungel; jeder von ihnen kann die Mixtur tragen.",
		["Pirate ghosts"] = "Piratengeister",
		["Ride back east past {area:75} and follow the road south-east to the small Horde post on the shore."] = "Reite zurück nach Osten an {area:75} vorbei und folge der Straße nach Südosten zum kleinen Hordeposten am Ufer.",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Reite nach Nordosten zum {area:76}. Die Kristalle stehen am Weg hinauf zum Käfig von {npc:5391}.",
		["Ride west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}."] = "Reite auf der Straße nach Westen zum Draeneilager bei {area:657}, nahe dem Weg vom {zone:1430} herein.",
		["Sawtooth crocolisks"] = "Sägezahnkrokilisken",
		["Skullsplitter warriors"] = "Krieger der Skullsplitter",
		["Take the road north out of {area:35}; Unbagwa sits on a hill in {area:1737}, east of the road."] = "Nimm die Straße nach Norden aus {area:35}; Unbagwa sitzt auf einem Hügel in {area:1737}, östlich der Straße.",
		["The Bloodsail ships"] = "Die Schiffe der Blutsegelbukaniere",
		["The boat lands in {area:35}'s harbour. The quest givers stand on the boardwalks around the harbour and in the inn."] = "Das Schiff legt im Hafen von {area:35} an. Die Questgeber stehen auf den Stegen rund um den Hafen und im Gasthaus.",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Die Gorillas streifen durch das Tal um Unbagwa. Die Alten lassen die Innereien fallen; jeder kann einen Fangzahn fallen lassen.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Die Pirscher-Raptoren jagen im Dschungel südlich von {object:3202}, hinaus Richtung Westküste.",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "Die drei geisterhaften Piraten spuken im Dschungel nördlich von {area:35}, nahe Zanzils Lagern: {npc:2535} und {npc:2536} stehen zusammen, {npc:2537} weiter östlich.",
		["The three ships lie off the {area:43}. The crews are 42-45, Stillwater 45, Keelhaul 46 and {npc:2546} 48: at 41 this is a fight for a group, or for the end of the guide. If you go, swim out and pull the crew to the rail one at a time. A scroll, {quest:624}, lies on the ships' decks: take it."] = "Die drei Schiffe liegen vor der {area:43}. Die Besatzungen sind 42-45, Stillwasser 45, Kielhol 46 und {npc:2546} 48: Mit 41 ist das ein Kampf für eine Gruppe oder für das Ende des Guides. Wenn du hingehst, schwimm hinaus und zieh die Besatzung einzeln an die Reling. Eine Schriftrolle, {quest:624}, liegt auf den Decks der Schiffe: Nimm sie mit.",
		["Venture Co. mine"] = "Mine der Venture Co.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "Westlich der Expedition stehen die Häuptlinge der Bloodscalp, {npc:1061} und {npc:1062}, zusammen in den Ruinen von Zul'Kunda. Räum zuerst ihre Wachen weg und zieh dann die beiden.",
		["Zanzil's camps"] = "Lager von Zanzil",
		["Zul'Kunda"] = "Ruinen von Zul'Kunda",
		["Zul'Mamwe"] = "Ruinen von Zul'Mamwe",
		["the {object:2076}"] = "{object:2076}",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} wird im {area:76} im Nordosten des Sumpfs gefangen gehalten. Befrei ihn und folge ihm hinaus; wehr die Sumpfkreaturen ab, die ihn verfolgen.",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Fly to {area:484}"] = "Flieg zum {area:484}",
		["Fly to {object:3202}"] = "Flieg nach {object:3202}",
		["Grimtotem camp"] = "Lager der Grimmtotem",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "Reite weiter nach Westen zur Küste. Die Küstenkriechertiefseher und Küstenkriecherschnappklauen an den Stränden lassen etwa bei jedem vierzigsten Kill das Notsignal von OOX-22/FE fallen: Fällt eins, benutze es, um die Quest zu starten.",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Kodos: {npc:3685}, neben {npc:3690} in {area:222}.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Nördlich der Gnolle halten die Oger einen Außenposten auf einem Hügel; zieh die Ogermagier zu dir. Das Kobalt ist in den Erdhügeln um den Außenposten, und die Schriftrolle liegt drinnen auf dem Boden.",
		["Ride north-east to the goblin harbour on the coast."] = "Reite nach Nordosten zum Goblinhafen an der Küste.",
		["Ride south-west to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "Reite nach Südwesten zu den Ogerruinen unterhalb von {area:1105}. Schamanen, Hexenmeister und Raufer füllen sie; die Magierlords am Südende tragen die Kugel.",
		["Riding at 40"] = "Reiten mit 40",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "Skelettpferde: {npc:4731}, neben {npc:4773} in {area:159}.",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Die Tauren der Grimmtotem lagern neben dem Hain der Grimmlingflitzer; Räuber, Naturalisten und Schamanen tragen alle Hörner.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "Der Bau der Zukk'ash gräbt sich in die Hügel südöstlich des Lagers; {quest:7731} wartet in seiner tiefsten Kammer.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "Der Schlachtplan liegt im Lager der Waldpfoten südlich von Mojache.",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Wölfe: {npc:3362}, neben {npc:4752}.",
		["Woodpaw battle map"] = "Schlachtplan der Waldpfoten",
		["Woodpaw north camp"] = "Nördliches Lager der Waldpfoten",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["for the {zone:1425}, around level 48"] = "für das {zone:1425}, etwa ab Stufe 48",
		["for {zone:1454}, around level 45"] = "für {zone:1454}, etwa ab Stufe 45",
		["water pouches in your bags"] = "Wasserbeutel in deinen Taschen",
		["{area:392} for the Felsteed"] = "{area:392} für das Teufelsross",
		["{npc:3690}, riding trainer"] = "{npc:3690}, Reitlehrer",
		["{npc:4752}, riding trainer"] = "{npc:4752}, Reitlehrer",
		["{npc:4773}, riding trainer"] = "{npc:4773}, Reitlehrerin",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: für {zone:1454}, etwa ab Stufe 45",
		["{quest:2863}: one hour from now"] = "{quest:2863}: eine Stunde ab jetzt",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "Drachenhöhlen",
		["Forest walkers"] = "Waldgänger",
		["Frayfeather hippogryphs"] = "Fransenfederhippogryphen",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "Nordwestlich an der Straße leben die Wutschrammyetis um die Höhlen in den Hügeln. Jeder kann auch {quest:7738} fallen lassen, der eine eigene Quest startet.",
		["Onyxia's eggs"] = "Onyxias Eier",
		["Rage Scar yetis"] = "Wutschrammyetis",
		["Ride back north to Brackenwall."] = "Reite zurück nach Norden nach Brackenwall.",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "Reite nach Nordwesten zur {area:1108}; {npc:14637} wartet am Steg.",
		["Ride south-west to the {object:2555}, then east through the {area:511}. The Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "Reite nach Südwesten zu {object:2555}, dann nach Osten durch {area:511}. Die Späher und Aschenschweife der Feuermähnen streifen mit den Sengenden Jungtieren und Welpen über seinen Nordrand; die Bannschuppen bewachen die Drachenhöhlen weiter südöstlich. Mok'Morokks Schnupftabak, Grog und Geldkassette liegen in den Lagern der Drachkin.",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Reite auf der Straße nach Westen; die Schriftrolle liegt am Wasser im äußersten Westen des Sumpfs.",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Meereselementare und Meeresschauer spülen um den Steg am Ufer entlang. Schrumpfe die Riesen zuerst mit {item:18904}: Geschrumpft verlieren sie ihre Elitestärke. Uferschreiter waten im Wasser; die Landgänger und Klippenriesen streifen weiter nördlich durch die Hügel.",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "Südlich des Tals nisten die Fransenfederhippogryphen an den Hängen; fast jeder lässt Sehnen und metallische Fragmente fallen.",
		["South-west, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "Im Südwesten hausen die Yetis in {area:1105}; jeder Yeti dort kann einen dicken Balg fallen lassen.",
		["Sprite darters and forest walkers"] = "Grimmlingflitzer und Waldgänger",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "Die Eier von Onyxia liegen in den Drachenhöhlen im Südosten von {area:511}, bewacht von den Bannschuppen; zerschlag fünf.",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Die Grimmlingflitzer schwirren über dem Hain gleich westlich des Lagers und tragen {item:9589}; die Wandernden Waldgänger, etwas weiter westlich, tragen die Abgesplitterten Baumstämme.",
		["The {area:511}"] = "{area:511}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "für {npc:5598} im {zone:1425}, etwa ab Stufe 48",
		["for the {zone:1425} owlbeasts, around level 48"] = "für die Eulenbestien im {zone:1425}, etwa ab Stufe 48",
		["the {object:2555}"] = "{object:2555}",
		["{quest:7738}, a rare drop"] = "{quest:7738}, eine seltene Beute",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Fly to {area:976}"] = "Flieg nach {area:976}",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "Seine nächste Bitte braucht das {item:10552} von Elitekultisten: Lass sie aus.",
		["Kalaran stands alone south of {area:1446}, at the edge of the Cauldron. Listen to his story."] = "Kalaran steht allein südlich von {area:1446}, am Rand des Kessels. Hör dir seine Geschichte an.",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "Nur mit dem {item:11818}: zurück nach Osten zum {object:173265} an der Grabungsstätte.",
		["Ride back north to {area:1446}. Stay here: the next guide starts with the flight to {area:75}."] = "Reite zurück nach Norden zur {area:1446}. Bleib hier: Der nächste Guide beginnt mit dem Flug nach {area:75}.",
		["Scrimshank's gear"] = "Scrimshanks Ausrüstung",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "Südlich von {area:982} halten die Oger der Dünenbrecher ihr Truppenlager, mit {npc:12046} am östlichen Ende. Grab zwischen den Kämpfen {quest:3161}-Ornamente aus.",
		["The {area:247}"] = "{area:247}",
		["The {object:179827} board"] = "Das Brett {object:179827}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "Nach Westen entlang der Straße nach Süden; {npc:7771} lagert bei den Ruinen an der {area:1938}. Leg seinen {item:9978} an: Er zeigt die vergrabenen Ornamente, hier und rund um das {area:983}.",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "Benutze westlich von Gadgetzan das {item:8584} neben dem Wasserloch im Trolllager.",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526} wächst im {zone:1425}, etwa auf Stufe 48",
		["the {object:173265}"] = "das {object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}, seltene Beute",
		["{item:8623}, a rare drop"] = "{item:8623}, seltene Beute",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955} wartet im Tal. Bring ihn den ganzen Weg zu seiner Frau {npc:6015} in {area:977}, nach Nordosten durch die Wüste: Bleib nah bei ihm, geh langsam für ihn und wehr ab, was ihn angreift. Steig nicht auf und nutz keinen Ruhestein außerhalb seiner Reichweite. {npc:8579} steht auch im Hafen.",
		["{npc:5955}'s escort"] = "Eskorte: {npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, neben dem Windreitermeister",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Zurück nach Westen zur {area:350}; Waldläuferinnen und Schützen bleiben nahe der Jagdhütte, Späher und Kundschafterinnen an den Hängen südlich davon.",
		["East of the village, the violet flower grows in the hills."] = "Östlich des Dorfs wächst der Violette Tragan in den Hügeln.",
		["Fly to {area:272}"] = "Flieg nach {area:272}",
		["Fly to {area:75}"] = "Flieg nach {area:75}",
		["Highvale"] = "Hochtal",
		["His next request, going on to the {area:355}, is for a group."] = "Seine nächste Bitte, weiter zu {area:355}, ist etwas für eine Gruppe.",
		["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of {area:354}. The Vessels of Tainted Blood sit on the lower terraces, and {npc:14757} is held at the top. Keep to the paths: the trolls inside are elite."] = "Malkors Schädel liegt auf einem Haufen unterhalb der Ruinen der Vilebranch, Malkors Knochen auf einem Haufen am Fuß von {area:354}. Die Gefäße mit besudeltem Blut stehen auf den unteren Terrassen, und {npc:14757} wird oben festgehalten. Bleib auf den Wegen: Die Trolle drinnen sind Elite.",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "Nördlich an der Küste steht der Picknickkorb von {npc:14731} auf der kleinen Insel; ein {npc:14748} bewacht ihn.",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Reite ganz nach Westen zur Stadt der Wildhammer, {area:348}, und leg die Nachricht beim Brunnen in ihrer Mitte ab. Die Stadt ist voller Wachen der Allianz: Rein, ablegen, raus.",
		["Ride back north to the bloodmages."] = "Reite zurück nach Norden zu den Blutmagiern.",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "Reite nach Westen aus {area:75} und nach Süden durch die Schlucht in die {zone:1419}; die beiden Blutmagier stehen gleich dahinter an der Straße.",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "Südlich der Jagdhütte halten die Trolle der Witherbark ihre Dörfer. Jeder von ihnen trägt einen Schädel: Mit zwanzig benutzt du {item:15002}, um Nimboyas geladene Pike zu machen, und pflanzt sie dann im Dorf auf.",
		["South-west again, the exile hides by the ruins of {area:353}."] = "Wieder nach Südwesten: Der Verbannte versteckt sich bei den Ruinen von {area:353}.",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "Die großen Schildkröten kriechen über die Strände nördlich des Dorfs. Die Portweinflaschen von {npc:2491} liegen auch an diesen Stränden, aber seine Quest ist nicht auf dieser Route. Ein Schnappkiefer kann selten das Notsignal von OOX-09/HL fallen lassen: Behalte es.",
		["The bloodmages"] = "Die Blutmagier",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "Die Kisten mit {item:8684} liegen um das verlassene Hordelager am {area:351}, zwischen den Schlammen.",
		["The next guide starts here, at {area:3317}."] = "Der nächste Guide beginnt hier, in {area:3317}.",
		["The secret lies on the {area:307}, above the beach."] = "Das Geheimnis liegt auf den {area:307}, über dem Strand.",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Ihre Folgequests wollen dieselben Teile noch einmal für einen Buffgegenstand und geben keine Erfahrung: Lass sie liegen.",
		["for {npc:6986} in {zone:1454}, around level 50"] = "für {npc:6986} in {zone:1454}, etwa ab Stufe 50",
