t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "Zurück nach Nordosten zu {npc:8420}.",
		["Back to {area:1099}"] = "Zurück nach {area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "Zurück zu {npc:11548} am Schrein; bleib westlich der Wachen an der {area:3137}.",
		["Back to {object:3202}"] = "Zurück nach {object:3202}",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "Reite weiter nach Süden nach {area:35}. {npc:7406} hat seine Werkstatt auf dem oberen Ring der Bucht.",
		["Follow the road north to {area:1237}, the Horde camp."] = "Folge der Straße nach Norden nach {area:1237}, dem Lager der Horde.",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Folge der Straße nach Süden; die Basilisken sonnen sich mitten im Dschungel auf den Felsen östlich davon. Ihre Splitter fallen oft.",
		["Frayfeather Hippogryphs"] = "Fransenfederhippogryphen",
		["Ironjaw Basilisks"] = "Eisenkieferbasilisken",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "Behalte die Lieferungen für {npc:4046}, {npc:8659} und {npc:6522}: Du kommst später durch {zone:1456}, {zone:1454} und {zone:1458}.",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "Behalte die Bezahlung von {npc:8659} und Ag'tors {quest:3504}: Sie gehen bei einem späteren Besuch zurück nach {area:1237}.",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "Behalte {quest:3444}: {npc:7771}s Truhe wird bei einem späteren Besuch geöffnet.",
		["Only once all three robots are home"] = "Erst wenn alle drei Roboter zu Hause sind",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Reite auf der Straße vom Splintertreeposten aus nach Osten. {npc:11548} wartet am {area:1235} gleich neben der Straße, ein paar Schritte westlich der {area:3137} der Allianz: Komm von Westen und halte dich von den Azshara-Schildwachen und Jarrodenus (Elite) fern.",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "Reite nach Nordosten zum Lager des Goblins auf den Klippen über dem Gebiet {area:1227}.",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "Reite nach Südwesten zu den Ruinen. Die vier Tafeln liegen in den Ruinen, bewacht von Naga der Grollflossen; jede Sirene oder Myrmidone kann die Rune von {npc:8420} tragen.",
		["Ride west back to {area:1237}."] = "Reite nach Westen zurück nach {area:1237}.",
		["Sprite Darters"] = "Grimmlingflitzer",
		["Take the zeppelin back to {zone:1454}."] = "Nimm den Zeppelin zurück nach {zone:1454}.",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Die Geister der Hochgeborenen spuken in den Ruinen gleich nördlich des Schreins; die Satyrn der Haldarr lagern etwas weiter nördlich.",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "Die Donnerkopfhippogryphen fliegen über die Hügel gleich südlich von {area:1237}.",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "Das Lager der Blutelfen liegt gleich südlich von {npc:8420}. Seine vier Ausrüstungsteile liegen in den Kisten im Lager.",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Die Feendrachen schwirren durch den Wald gleich westlich des Lagers. Benutze das Gefäß an jedem, den du tötest.",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Die Hippogryphen nisten auf den Hügeln südwestlich des Lagers. Töte einen und benutze dann das Muisekgefäß an seiner Leiche.",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "Die Treants wandern auf den Waldwegen zwischen dem Lager und der Mitte von {zone:1444}; es gibt nur wenige, also such entlang der Pfade.",
		["The {object:2076} beside {npc:2519}"] = "Der {object:2076} neben {npc:2519}",
		["To {object:3202}"] = "Nach {object:3202}",
		["Undamaged Hippogryph Feathers"] = "Unbeschädigte Hippogryphenfedern",
		["Wandering Forest Walkers"] = "Wandernde Waldgänger",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "Der Turm von Xylem steht auf der Klippe gleich nördlich von {area:1237}; der Pfad windet sich an seiner Nordseite hinauf.",
		["Zeppelin to {zone:1454}"] = "Zeppelin nach {zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}, die Gasse",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "Der Teer für {npc:7876} und Pestlezuggs Proben stammen aus {zone:1449}.",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}, neben dem Windreitermeister",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}, am Ostrand des Lagers: keine Erfahrung, nur ein Teleport zum Azsharaturm",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761} wird im nächsten Guide gesammelt; {npc:4046}s Bezahlung geht später zurück an {npc:8587}.",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back north-east to {area:251}."] = "Zurück nach Nordosten zum {area:251}.",
		["Back to {area:2268}"] = "Zurück zur {area:2268}",
		["Bridge into {area:254}"] = "Brücke in den Berg ({area:254})",
		["Cross the south of the crater to the pylon on the western cliffs."] = "Durchquere den Süden des Kraters zum Pylon auf den westlichen Klippen.",
		["Eastern Pylon"] = "Östlicher Kristallpylon",
		["Fly to {area:340}"] = "Flieg nach {area:340}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "Folge den Klippen nach Süden zum {quest:3821}, dem Hügel der Oger der Feuermägen. Die Überreste von {npc:9136} liegen an seinem Fuß.",
		["Free Darrowshire Spirits: talk to them"] = "Befreie Geister von Darrowshire: Sprich mit ihnen",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "Sammle ab jetzt jeden Machtkristall (blau, grün, rot, gelb) und jeden Haufen {quest:3761} auf deinem Weg ein: insgesamt 25 Erde, 20 für Hamuul und 5 für Pestlezugg.",
		["Into the {zone:1427}"] = "In die {zone:1427}",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "Behalte {npc:10267}s Brief: {quest:4808} ist in {area:2255}, {zone:1452}.",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "Behalte {quest:4147} von {npc:9118} und den Brief von {npc:8737} für spätere Guides.",
		["Keep {quest:5152}: Marlene lives at {area:197} in the {zone:1422}."] = "Behalte {quest:5152}: Marlene wohnt am {area:197} im Gebiet {zone:1422}.",
		["Lar'korwi Mates"] = "Lar'korwi-Weibchen",
		["North of Torwa, a dead Threshadon lies by the water."] = "Nördlich von Torwa liegt ein toter Dreschadon am Wasser.",
		["Northern Pylon"] = "Nördlicher Kristallpylon",
		["Out of the refuge"] = "Raus aus der Zuflucht",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "Pestlezuggs nächste Quest braucht die {npc:10041}, einen Elite-Boss. Überspringe sie.",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Reite die Ostseite des Kraters hinab zum Pylon auf den östlichen Klippen.",
		["Ride north back to {area:541}."] = "Reite nach Norden zurück nach {area:541}.",
		["Ride south back to the road and follow it east across the whole zone to {area:2268}."] = "Reite nach Süden zurück zur Straße und folge ihr nach Osten durch das ganze Gebiet zur {area:2268}.",
		["Stegodons and ravasaurs"] = "Stegodons und Ravasaurier",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "Nimm einen {object:176092} aus der Kiste neben Derrington für {quest:5096}, die du auf dem Rückweg erledigst. Leg die {quest:5401} an: Geißelsteine fallen nur, solange du sie trägst.",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "Nimm den Pass an der Westseite von {area:340} in die {zone:1427} und reite dann nach Süden durch die Schlucht zur langen Brücke in den Berg ({area:254}). Folge drinnen den Kettenstegen nach unten und verlass ihn durch den Südausgang; bleib von den Wegen zu den Dungeonportalen fern.",
		["The Gorishi hive"] = "Der Schwarm der Gorishi",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "Die Lar'korwi-Weibchen streifen durch den Dschungel nordwestlich von {npc:9619}.",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "Der Kopf der Puppe und ihre beiden Seiten liegen in den Häusern um {npc:10926}; füge sie in deinen Taschen zusammen.",
		["The expedition's lost equipment lies in the south-west jungle."] = "Die verlorene Ausrüstung der Expedition liegt im südwestlichen Dschungel.",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "Der Berg lässt dich neben der {area:252} hinaus, voller Orcs der Stufe 55-57. Folge der Straße an den nördlichen Klippen nach Osten zum Lager der Horde am {area:251}.",
		["The next guide starts here, at the chapel's flight master."] = "Der nächste Guide beginnt hier, beim Flugmeister der Kapelle.",
		["The pylon stands on the slope east of the refuge."] = "Der Pylon steht am Hang östlich der Zuflucht.",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Das Floß liegt am Ufer des südöstlichen Sees; das kleine Bündel liegt daneben im Wasser.",
		["Use the Mangled Journal to start it"] = "Benutze Ein zerfleddertes Tagebuch, um sie zu starten",
		["Western Pylon"] = "Westlicher Kristallpylon",
		["With {npc:11063}'s quest in your log, slain Scourge sometimes leave a {npc:11064}; talk to it to free it. Kill undead on the ride south-west to {area:2262}."] = "Mit {npc:11063}s Quest im Questlog hinterlässt erschlagene Geißel manchmal einen {npc:11064}; sprich mit ihm, um ihn zu befreien. Töte Untote auf dem Ritt nach Südwesten nach {area:2262}.",
		["{item:11116}, a rare drop"] = "{item:11116}, seltene Beute",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}, {object:36078}, neben dem Fledermausführer",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "{npc:10926}s Geist steht in den Ruinen von {area:2262} im Südwesten.",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}, {object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}, im Apothekarium: Die Phiolen füllst du später in {zone:1447}",
		["{npc:9618}, just outside"] = "{npc:9618}, gleich draußen",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619} lagert in der Südostecke des Kraters.",
		["{npc:9998}, at the entrance"] = "{npc:9998}, am Eingang",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, am Eingang der Zuflucht",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822} durchstreift die Höhlen und Minenstollen des {quest:3821}; ist er nicht da, räum die Oger an den Eingängen weg, bis er zurückkommt.",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "Zurück nach Norden nach {area:1763}. Füll {npc:10922}s Feldflasche am verderbten Mondbrunnen mitten im südlichen Lager.",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "Derringtons Wachtürme, Vandis' Kessel und {npc:11615}s Fass erledigst du bei einem späteren Besuch: Behalte sie.",
		["Diseased Wolves"] = "Kranke Wölfe",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "Östlich vom Blutgiftposten liegt das kraterübersäte Tal, wo die Entropischen Bestien und Schrecken umherstreifen. Töte je zwei davon und geh dann zu jedem der drei Krater mit Teufelswasser.",
		["Follow the road north-east to {area:1767}. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a {item:11503}; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo."] = "Folge der Straße nach Nordosten zum {area:1767}. Die Wucherborkenschinder und -schredder auf der Ostseite des Waldes tragen je einen {item:11503}; Wutklauengrizzlys und Teufelspfotenverheerer streifen für Talo durch denselben Wald.",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "Folge der Straße nach Nordwesten. Den Süden von {area:1763}, um seinen verderbten Mondbrunnen, halten Kultisten, Adepten, Wachen und Hunde des Schattenrats.",
		["He camps by the {area:202}, south-east of {area:200}."] = "Er lagert beim {area:202}, südöstlich von {area:200}.",
		["Jadefire moonwell"] = "Mondbrunnen der Jadefeuersatyrn",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "Behalte den Zweig: {npc:5770} ist in {zone:1456}.",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "Behalte {quest:5158}: {npc:5901} ist im {zone:1413}.",
		["Keep {quest:8465} for {zone:1452}."] = "Behalte {quest:8465} für {zone:1452}.",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "Ritter und Magier arbeiten im {area:192}; die Sanitäter und Jäger lagern südlich davon.",
		["Northern crater"] = "Nördlicher Krater",
		["Only if a {item:13140} dropped: use it to start the quest, then free {npc:11018} in her cage in {area:1770}, the cave at the north end of {area:1763}, and escort her out."] = "Nur wenn {item:13140} gefallen ist: Benutze ihn, um die Quest zu starten, befrei dann {npc:11018} aus ihrem Käfig in {area:1770}, der Höhle am Nordende von {area:1763}, und eskortiere sie hinaus.",
		["Only if you rescued {npc:11018}: the succubus {npc:9518} waits in the middle of {area:1763}, beside the {npc:11020}."] = "Nur wenn du {npc:11018} gerettet hast: Die Sukkubus {npc:9518} wartet mitten in {area:1763}, neben {npc:11020}.",
		["Only with 5 Deadwood Headdress Feathers"] = "Nur mit 5 Kopfputzfedern der Totenwaldfelle",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "Reite zurück nach Süden an {area:1763} vorbei zum verderbten Mondbrunnen der Jadefeuersatyrn und füll dort {npc:9996}s Fläschchen.",
		["Ride north along the eastern hills; {npc:1855} lives in a small house by the {area:2619}, at the border with the {zone:1423}."] = "Reite an den östlichen Hügeln entlang nach Norden; {npc:1855} lebt in einem kleinen Haus am {area:2619}, an der Grenze zu den {zone:1423}.",
		["Ride north up the road again."] = "Reite die Straße wieder nach Norden hinauf.",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Reite nach Nordwesten nach Andorhal. {npc:10667} wartet im zerstörten Gasthaus auf der Westseite der Stadt; die Skelette drinnen sind 54-57, also bleib am Rand.",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "Reite nach Südwesten am Teufelssteinhof vorbei und folge der Straße nach Westen zurück zum {area:152}.",
		["Ride west to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "Reite nach Westen zum {area:192}; {npc:11610} versteckt sich auf dem Hügel nordöstlich davon.",
		["Ror stands at the far south end of {area:1761}."] = "Ror steht am äußersten Südende von {area:1761}.",
		["Scarlet Crusade"] = "Scharlachroter Kreuzzug",
		["Southern crater"] = "Südlicher Krater",
		["Southern {area:1763}"] = "Südliches {area:1763}",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "Bring das Kätzchen zum selben Mondbrunnen und lass es dort frei; sobald es sich in {npc:10042} verwandelt hat, bring es zurück zu {npc:9996} und klick es an, um es zu übergeben.",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Die Annalen liegen zwischen den Modrigen Folianten im Rathaus von Andorhal; öffne sie, bis du den richtigen findest.",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "Das Furbolgdorf der Totenwaldfelle gleich westlich des Tunnels. {npc:9462} (56) steht zwischen ihnen. {npc:11557}, ein freundlicher Furbolg, sitzt am Nordende des Dorfs.",
		["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your {area:1769} reputation; keep the headdress feathers."] = "Das Furbolgdorf der Totenwaldfelle liegt gleich südlich des Refugiums. Jeder getötete Totenwaldfell erhöht auch deinen Ruf bei der {area:1769}; behalte die Kopfputzfedern.",
		["The Horde camp just north of {area:1763}."] = "Das Hordelager gleich nördlich von {area:1763}.",
		["The Jadefire moonwell"] = "Der Mondbrunnen der Jadefeuersatyrn",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "Das Tagebuch liegt im Bauernhaus, der Schrank steht drinnen und der Abort dahinter. Ein {npc:10816} trägt den Schlüssel zum Abort; {npc:10836} kommt heraus, wenn du den Abort öffnest, und trägt den Schlüssel zum Schrank.",
		["The druids' camp is just past the border."] = "Das Lager der Druiden liegt gleich hinter der Grenze.",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "Die Straße endet bei {npc:15395}, vor dem Tunnel der {area:1769} im äußersten Nordosten.",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "Die Wölfe streifen über die Felder zwischen Andorhal, {area:200} und {area:202}. Erledige sie auf dem Rückritt nach Osten.",
		["The {area:1763} moonwell"] = "Der Mondbrunnen von {area:1763}",
		["Western crater"] = "Westlicher Krater",
		["{area:200} farmhouse"] = "Bauernhaus von {area:200}",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}: Die Eulenbestien sind in {zone:1452}",
		["{npc:10840}, at the graveyard's south end"] = "{npc:10840}, am Südende des Friedhofs",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}, am Südrand des Lagers",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "{npc:1855}s Jagden sind in den {zone:1423}: Behalte sie für später.",
		["{npc:9529}, just west of the camp"] = "{npc:9529}, gleich westlich des Lagers",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}, auf der Westseite des Refugiums",
		["{npc:9996}'s kitten"] = "{npc:9996}s Kätzchen",
		["{quest:5210} goes to {area:2268}: keep it for later."] = "{quest:5210} führt zur {area:2268}: Behalte sie für später.",
		["{quest:8470}, a rare drop"] = "{quest:8470}, eine seltene Beute",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Fly to {area:1099}"] = "Flieg zum {area:1099}",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Gregor's and Harlo's quests lead to other zones: keep them."] = "Gregors und Harlos Quests führen in andere Gebiete: Behalte sie.",
		["Ice Thistle yetis"] = "Eisdistelyetis",
		["In the {object:172958}."] = "Im {object:172958}.",
		["In the {object:172961}."] = "Im {object:172961}.",
		["Linken's letter"] = "Linkens Brief",
		["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "Matriarchinnen und Patriarchen schlagen hart zu: Zieh sie einzeln.",
		["Pristine Yeti Horns"] = "Makellose Yetihörner",
		["Raging Owlbeasts"] = "Tobende Eulenbestien",
		["Ride west along the road past {area:2251}; Raging Owlbeasts roam the hills north of it."] = "Reite auf der Straße nach Westen am {area:2251} vorbei; Tobende Eulenbestien streifen durch die Hügel nördlich davon.",
		["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "Das Furbolgdorf füllt das Tal nordöstlich von {area:2255}. Töte zuerst die Schamanen; sie heilen. {npc:10738} in der Höhle hinten ist Elite: Bleib draußen.",
		["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "Die Yetihügel beginnen gleich südöstlich von {area:2255}. Jeder Yeti lässt Fell fallen; nur Matriarchinnen und Patriarchen lassen Hörner fallen, also heb die für nach der Abgabe auf.",
		["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "Umis dritter Streich gilt Goblins in {area:976} und Un'Goro: Behalte ihn für später.",
		["{area:2255} is the goblin town on the east side of the valley."] = "{area:2255} ist die Goblinstadt auf der Ostseite des Tals.",
		["{item:12771}, a rare drop from the Winterfall furbolgs"] = "{item:12771}, eine seltene Beute der Winterfell-Furbolgs",
		["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}: Der letzte Guide bindet dich hier, daher ist das meist sofort abgehakt",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} auf der {area:1639}; {npc:246344}",
		["{npc:7775}, a dwarf, camps in the {area:1137} north-west of {area:1099}; he has the elixir."] = "{npc:7775}, ein Zwerg, lagert in {area:1137} nordwestlich vom {area:1099}; er hat das Elixier.",
		["{npc:9298} camps among the steaming pools of {area:2246}, in the west of the valley."] = "{npc:9298} lagert zwischen den dampfenden Becken von {area:2246}, im Westen des Tals.",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123} wartet in {zone:1450}: Behalte sie für später.",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909} kommt von {npc:7775} in {zone:1444}, später in diesem Guide.",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084} wird bei {object:176091} im {zone:1448} abgegeben, auf einer späteren Reise.",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}, eine seltene Beute der Winterfell-Furbolgs",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "Das gereinigte Wasser geht zum {area:2479} im {zone:1448}: Behalte es für später.",
		["Fly to {area:1237}"] = "Flieg nach {area:1237}",
		["Fly to {area:1637}"] = "Flieg nach {area:1637}",
		["Fly to {area:392}"] = "Flieg nach {area:392}",
		["In the {object:172958}."] = "Im {object:172958}.",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "Livs Werkstatt ist am Nordende der Docks von {area:392}; {object:149036} steht darin.",
		["Only with {quest:79095} from {area:159}'s alchemy shop in your bags (the Library Books guide)"] = "Nur mit {quest:79095} aus dem Alchemieladen von {area:159} in deinen Taschen (der Guide Bibliotheksbücher)",
		["Ride back west to {area:1237}."] = "Reite zurück nach Westen nach {area:1237}.",
		["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "Reite nach Osten zu den Ruinen an der Küste. Füll Cuelys vier Phiolen an den Gezeitentümpeln am Ufer; Naga der Grollflossen patrouillieren dazwischen.",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}."] = "Die Blutelfen lagern auf den Klippen im Nordosten, an der {area:1227}.",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, im Apothekarium",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}, {object:172957}: Behalte sie für {zone:1451}",
		["{npc:256386} stands in the {area:380}. Open each crate she hands you and bring back what is inside."] = "{npc:256386} steht in {area:380}. Öffne jede Kiste, die sie dir gibt, und bring zurück, was darin ist.",
		["{npc:256386}'s crates"] = "Kisten von {npc:256386}",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901} lagert am Ufer gleich nördlich von {area:392}.",
		["{npc:8393}, beside him"] = "{npc:8393}, neben ihm",
		["{npc:8403}, nearby"] = "{npc:8403}, in der Nähe",
		["{npc:8578}'s camp"] = "Lager von {npc:8578}",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}, {object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050} geht zurück zu {npc:10778} in den {zone:1422}: Behalte sie.",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["Both quests lead to {zone:1451}: keep them."] = "Beide Quests führen nach {zone:1451}: Behalte sie.",
		["Fly to {area:1099}. The hippogryph nests are in the south of {zone:1444}; each holds an egg for the {object:142071}."] = "Flieg zum {area:1099}. Die Hippogryphennester sind im Süden von {zone:1444}; jedes enthält ein Ei für {object:142071}.",
		["Fly to {area:1638}"] = "Flieg nach {area:1638}",
		["Fly to {area:2268}"] = "Flieg zur {area:2268}",
		["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "Rasende Seuchenhunde und Monströse Seuchenfledermäuse teilen sich die Felder um {area:2272} und den {area:2271}, südlich von {area:2273}.",
		["Moontouched Owlbeasts"] = "Mondbestrahlte Eulenbestien",
		["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "Nur wenn {quest:8471} für dich gefallen ist: {npc:11558} wartet am Eingang der {area:1769} im {zone:1448} und spricht erst ab neutralem Ruf bei der Holzschlundfeste mit dir.",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "Reite nach Osten nach {area:2255} und von dort nach Norden; die Mondbestrahlten Eulenbestien streifen durch die Hügel an den Südhängen von {area:2241}. Zieh sie einzeln.",
		["Ride west to the {area:2260}."] = "Reite nach Westen zu {area:2260}.",
		["The {object:142071} machine"] = "Die Maschine {object:142071}",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "Der Geist {npc:11140} steht bei einer Hütte im {area:2627}, in der Nordwestecke.",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{npc:3033} auf der {area:1639}; {npc:246344}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771} lagert an der Straße zur {area:1336}, südlich von {area:976}.",
		["{npc:9299} is a ghost at the graveyard just north of {area:976}; the Conspicuous Gravestone is south of it, outside the town wall."] = "{npc:9299} ist ein Geist auf dem Friedhof gleich nördlich von {area:976}; Ein verdächtiger Grabstein liegt südlich davon, außerhalb der Stadtmauer.",
		["{quest:3914} goes back to Linken in Un'Goro: keep it."] = "{quest:3914} geht zurück zu Linken in Un'Goro: Behalte sie.",
		["{quest:5086} are in {zone:1448}, on a later trip: keep it if you have it."] = "{quest:5086} sind im {zone:1448}, auf einer späteren Reise: Behalte sie, falls du sie hast.",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "Die Gegenstände für {quest:5168} liegen in den späteren Gebieten der Pestländer: Behalte sie.",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["Andorhal watchtowers and silos"] = "Wachtürme und Silos von Andorhal",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "Zurück zum Südwindposten und steig auf den Turm. Wenn du oben den Bau aufscheuchst, kommen Wegelagerer des Ashischwarms heraus; einer trägt {item:17346}.",
		["Back to {area:3425}"] = "Zurück nach {area:3425}",
		["Dredge Crushers and Pincers"] = "Baggerbrecher und Steinpanzerzangen",
		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "Weiter östlich an der Straße bewacht {npc:11077} den Kessel bei {area:200}.",
		["Flayers and Rock Stalkers"] = "Schinder und Felspirscher",
		["Fly to {area:976}. The {object:142071} stands in the middle of town."] = "Flieg nach {area:976}. Der {object:142071} steht mitten in der Stadt.",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Geh nach Norden entlang der westlichen Dünen; Baggerbrecher und Steinpanzerzangen ziehen von hier bis zurück zur Burg umher.",
		["Mark {npc:10902} with the {item:12815}"] = "Markiere {npc:10902} mit der {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Markiere {npc:10903} mit der {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Markiere {npc:10904} mit der {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Markiere {npc:10905} mit der {item:12815}",
		["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "Nach Norden zum Holzlager Northridge; stell das Fass mit Pestland-Termiten mitten in der Mühle ab.",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "Reite nach Osten zu {npc:1855}s Hütte am Fluss {area:2619} und hör ihn an.",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "Reite nach Nordosten zur {area:3077}; du verlässt {zone:1451} durch den Pass daneben.",
		["Ride north-east to {area:3447}."] = "Reite nach Nordosten zu {area:3447}.",
		["Ride north-west to {npc:1855}'s hut."] = "Reite nach Nordwesten zu {npc:1855}s Hütte.",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "Reite nach Süden nach Andorhal. {npc:10667} wartet im verfallenen Gasthaus auf der Westseite der Stadt. Stell dich mit der {item:12815} in den Eingang jedes der vier Türme, um ihn zu markieren; halte dich an den Stadtrand. Benutze den {item:12627} bei den Silos mitten in der Stadt, um Temporale Parasiten hervorzulocken.",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "Reite nach Südosten zu {area:3447} unter den Klippen des Un'Goro-Kraters.",
		["Ride south-west to the ruins of {area:2738}. The {object:179565} for {npc:11801} sits inside one of the ruined houses."] = "Reite nach Südwesten zu den Ruinen vom {area:2738}. Der {object:179565} für {npc:11801} steht in einem der verfallenen Häuser.",
		["Ride south-west to {npc:10667} in Andorhal."] = "Reite nach Südwesten zu {npc:10667} in Andorhal.",
		["Ride west to the Horde camp north of {area:2744}."] = "Reite nach Westen zum Lager der Horde nördlich vom {area:2744}.",
		["Scourge Champions"] = "Champions der Geißel",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "Champions der Geißel streifen durch das Tal ({area:2270}) nördlich der Kapelle. Führe {npc:11063}s {item:13156} über jeden, den du tötest: Die Schädel, die mitschwingen, sind die, die er will.",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Silithystgeysire brechen überall in der südlichen Wüste aus. Lauf in das Silithyst, das einer zurücklässt, und bring es zum Silithyst Extractor der Horde in Kirikas Lager; Kämpfen oder Aufsteigen lässt es fallen.",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Steinpanzerschinder und Felspirscher streifen durch die Dünen südwestlich von Kirikas Lager.",
		["The libram lies further north, on the way to {area:190}."] = "Davils Buchband liegt weiter nördlich, auf dem Weg nach {area:190}.",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "Der Pass aus dem Un'Goro-Krater endet an der {area:3077}, dem Friedhof im Nordosten von {zone:1451}. {npc:13220} steht zwischen den Gräbern.",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "Der Ranzen liegt in den Bergen im äußersten Süden, hinter Bronzebeards Lager. Totenstachel, ein Eliteskorpid, patrouilliert in der Nähe: Schnapp ihn dir, während er weg ist.",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "Der Schild liegt bei {area:201}, südlich von {npc:1855}s Hütte.",
		["The spare texts from the cultists"] = "Die übrigen Texte von den Kultisten",
		["Twilight Vanguard"] = "Vorhut der Twilight",
		["Use {npc:10980} on {npc:10977}"] = "Benutze {npc:10980} an {npc:10977}",
		["West to the {area:152}. The next guide starts in the {zone:1458}, a short ride west."] = "Nach Westen zum {area:152}. Der nächste Guide beginnt in {zone:1458}, ein kurzer Ritt nach Westen.",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "Die Schlacht um Darrowshire von {npc:10667} endet gegen Elitegegner. Überspring sie.",
		["{npc:11803} walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for {npc:15306} and ten for Ortell."] = "{npc:11803} läuft durch das Lager der Vorhut im äußersten Südwesten. Jeder Kultist hier lässt Verschlüsselte Texte der Twilight fallen, ob Quest oder nicht: Sammle zwanzig, zehn für {npc:15306} und zehn für Ortell.",
		["{npc:11804} stands in the outpost west of {area:3425}. Top your Encrypted Twilight Texts up to twenty on the cultists here."] = "{npc:11804} steht im Außenposten westlich von {area:3425}. Füll deine Verschlüsselten Texte der Twilight bei den Kultisten hier auf zwanzig auf.",
		["{npc:15200} holds the camp in the west."] = "{npc:15200} hält das Lager im Westen.",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}, auf der Westseite der Burg",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Back south to the Sanctuary, a short ride."] = "Zurück nach Süden zum Refugium, ein kurzer Ritt.",
		["Dungeon instead of grinding"] = "Dungeon statt Grinden",
		["Grind to 60"] = "Grinde bis 60",
		["In {zone:1454}: fly from {area:2255}"] = "In {zone:1454}: Flieg von {area:2255}",
		["In {zone:1456}: fly from {area:2255}"] = "In {zone:1456}: Flieg von {area:2255}",
		["Only with 30 {quest:6031}, and only at Neutral with the Timbermaw: follow the road north to {area:1769}; {npc:11557} trades just inside the entrance."] = "Nur mit 30 {quest:6031} und nur bei Neutral mit der Holzschlundfeste: Folge der Straße nach Norden zur {area:1769}; {npc:11557} handelt gleich hinter dem Eingang.",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "Optional. {area:2279}, {area:2057}, die Untere Blackrockspitze oder {area:1584} mit einer Gruppe statt Grinden bringt dich schneller ans Ziel.",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "Optional: Mit einer Gruppe ersetzt ein Dungeon der Stufe 55-60 das Grinden unten.",
		["Ride east along the road to {area:2255}."] = "Reite auf der Straße nach Osten nach {area:2255}.",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "Reite auf der Straße nach Norden an {area:1763} vorbei zum {area:1997}.",
		["South to the Sanctuary once more."] = "Noch einmal nach Süden zum Refugium.",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}s Die Splitter der Teufelsranke braucht {area:2577}. Überspringe sie.",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298} schickt dich als Nächstes zu {npc:10738}, einem Elite in seiner Höhle. Überspringe es.",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "Gepanzerte Skorpide kriechen über die Ebenen westlich von {area:362}. Zähm einen und kehr dann zu {npc:3171} zurück.",
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "Zurück nach Osten zum Ufer nördlich von {npc:275657}. Späher und Bedienstete der Grollflossen halten den Strand unterhalb von {area:370}. Jäger: Zähm am Strand einen {npc:3107}.",
		["Back south to {area:362}."] = "Zurück nach Süden nach {area:362}.",
		["Back to the Den"] = "Zurück zum Höhlenbau",
		["Back to {area:362}."] = "Zurück nach {area:362}.",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Zurück zu {npc:5875} in {object:172960}. Benutze dort {item:7464} am Beschwörungskreis und besiege den Leerwandler, um ihn zu binden.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Kultisten der Burning Blade halten die Höhlen von {quest:827}; jeder lässt {item:4871} fallen. {npc:3204}, ein Hexenmeister der Stufe 14, steht tief drinnen und lässt {item:4903} fallen.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Teufelspirscher streifen über den Hang unterhalb der Höhle, auf der Nordseite des Tals.",
		["Follow the road north from {area:362} to {zone:1454}'s main gate, just west of {area:817}. {npc:3352} stands with the hunter trainers in the {object:172958}."] = "Folge der Straße von {area:362} nach Norden zum Haupttor von {zone:1454}, gleich westlich von {area:817}. {npc:3352} steht bei den Jägerlehrern im {object:172958}.",
		["Free {npc:275811} and see her safely out of the crag"] = "Befrei {npc:275811} und bring sie sicher aus dem Felsen",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Geh nach Nordosten zur Straße Richtung {zone:1454}. {npc:3293} lagert daneben; die gestohlenen Säcke liegen entlang der Straße südlich von ihm.",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "Geh nach Süden über die Inseln. Die Loa-Götzen liegen überall auf den südlichen Inseln; Voodootrolle und Verhexte Trolle halten sie und lassen die Verhexten Anhänger ({item:275724}) fallen. {quest:826} und Minshinas Käfig sind auf der südlichsten Insel.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Geh in der Höhle an der ersten Gabelung geradeaus, dann rechts, und folge dem Bach zu deiner Linken bis zum Wasserfall: Die Hacke leuchtet am Wasser, hinter einer Felssäule.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Halte dich in der Höhle immer an der rechten Wand, über den Bach: {npc:3183} wartet am Ende.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Mishas Hütte steht südlich der Echsen. Die Krokilisken am {area:814} im Westen tragen {item:4891}.",
		["Prickly pears"] = "Kaktusfeigen",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Stacheleber und Späher halten die Hütten westlich des Orts; Staubläufer und Schlachtwachen halten die Lager weiter westlich.",
		["Spitelash naga"] = "Naga der Grollflossen",
		["Tame it with the {item:15908}"] = "Zähm ihn mit {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Die Burg steht an der Küste südöstlich von {area:362}. Axt, Bogen und Schild der Räuber liegen an ihrem Rand. Matrosen und Marinesoldaten lassen {item:4870} fallen. {npc:3192} wartet oben in der Burg; sein Schlüssel öffnet die Truhe neben ihm, in der {item:4881} liegt.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Die Kaktusfeigen wachsen zwischen den Hütten der Stacheleber gleich westlich des Orts.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Die Waffen liegen um den Höhlenbau und den Übungsplatz; die Scheckigen Eber streifen über den ganzen Talboden.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} steht in {area:817}, zwischen den Kultisten, die du gerade bekämpft hast.",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "Donnerechsen und Blitzechsen grasen jenseits der Brücke auf dem {area:369}; jede kann {item:6486} fallen lassen.",
		["Thunder lizards across the river"] = "Donnerechsen jenseits des Flusses",
		["Training weapons and boars"] = "Übungswaffen und Eber",
		["Wake {quest:5441} with the {item:16114}"] = "Weck {quest:5441} mit {item:16114}",
		["the {object:654925} on the ground beside her"] = "{object:654925} neben ihr auf dem Boden",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} liegt westlich von Sen'jin. Die drei Angriffspläne liegen zwischen den Zentaurenzelten auf dem Boden. {npc:275811} wird ebenfalls am Felsen festgehalten.",
		["{area:817}'s mouth"] = "Eingang von {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, wo du startest",
		["{npc:265809}'s campfire"] = "Lagerfeuer von {npc:265809}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: nur für Verzauberer, die Rückstände werden aus Verhexten Anhängern ({item:275724}) entzaubert",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} steht am Ufer östlich von {area:362}. Dreizack, Banner und Dolch liegen um ihn herum am Strand.",
		["{npc:3102} hooves"] = "{npc:3102}-Hufe",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, zurück in {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, ein Elite-Meeresriese",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} steht gleich hinter dem Höhleneingang; {npc:3159} hinten in der Höhle hinter ihm.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} wartet im Höhlenbau, dem Gebäude gleich westlich von {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, im Wachturm",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}, der Kriegerlehrer neben dem Höhlenbau",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}, der Jägerlehrer neben dem Höhlenbau",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}, der Schurkenlehrer im Höhlenbau",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}, der Hexenmeisterlehrer hinten in der Höhle",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}, der Schamanenlehrer neben dem Höhlenbau",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} liegt verwundet am Fuß der Hügel nordwestlich des Höhlenbaus.",
		["{npc:3294}, by the inn"] = "{npc:3294}, beim Gasthaus",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}, die Magierlehrerin, am Eingang zum Höhlenbau",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} steht vor dem Höhlenbau. {area:639} ist der Hügel gleich südlich davon: Trink dort {item:6635}, um {npc:5891} zu sehen, und bring dann {item:6656} zurück zu {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} und dein {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, auf dem {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} steht auf der Straße am östlichen Ausgang des Tals.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, am Kochfeuer",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} lagert auf dem Hügel westlich des Nagastrands, südlich von {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Das Haupttor von {zone:1454} liegt gleich westlich von {area:817}. {npc:5875} steht in {object:172960}, der Schlucht unter dem {object:172982}.",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "Aanders und die gefallenen Wachen liegen gleich südwestlich des Turms. Nimm Raanis Glücksfeder und das Schattensang-Familiensiegel von den Leichen.",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "Zurück in {quest:92529}: Sturmrufer und {npc:251662} füllen das Dorf, die Vorratskisten stehen zwischen den Häusern und {npc:251966} wartet an seinem Südostende.",
		["Back to {area:16635}"] = "Zurück nach {area:16635}",
		["Back to {area:16638}"] = "Zurück nach {area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "Zurück zu {npc:268592}. Warte, bis er {npc:268762} entzündet, und trag die Flamme dann direkt zu {npc:268679} neben {npc:252382} in {area:16638}, bevor der Timer abläuft.",
		["Find {npc:258130}"] = "Finde {npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle."] = "Folge der Straße nach Süden nach {area:16624}, in der Mitte der Insel.",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "Geh nach Norden in {area:16631}; {npc:257944} lagert an seinem Südrand.",
		["Head north-east to the {area:17675}. The Al'Aketh camp is just west of it, with {npc:252666} at its north end. Every cultist can drop a windstone charm."] = "Geh nach Nordosten zum {area:17675}. Das Lager der Al'Aketh ist direkt westlich davon, mit {npc:252666} an seinem Nordende. Jeder Kultist kann ein Windsteinamulett fallen lassen.",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "Geh nach Südwesten zum {area:17674}. {npc:252155} ist oben; {item:254871} liegt neben ihm.",
		["Heal the injured druids in the Nightfang Den"] = "Heile die verletzten Druiden im Nachtfangbau",
		["Leaving {area:16635}"] = "Abschied von {area:16635}",
		["Listen to {npc:252448}'s story"] = "Hör dir die Geschichte von {npc:252448} an",
		["Listen to {npc:256083}"] = "Hör {npc:256083} zu",
		["Northern {zone:1412}"] = "Nördliches {zone:1412}",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "Lästige Zirrusfliegen und {npc:250873} streifen durch den Hain gleich südöstlich des Dorfs.",
		["Raw Windstones"] = "Rohe Windsteine",
		["Skyhoppers"] = "Himmelshüpfer",
		["Skyhoppers hop about the fields just west of Valennia."] = "Himmelshüpfer hüpfen über die Felder gleich westlich von Valennia.",
		["Spread the {item:278078} off {area:1641}"] = "Verstreu {item:278078} von der {area:1641}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "Sturmäpfel und Flatterfliegenstaub liegen überall im Obstgarten; Hungrige Banditen plündern ihn. Windschreiter grasen auf den Feldern östlich davon. Das kaputte Konstrukt schwebt am Nordrand des Obstgartens.",
		["Tame {npc:250874}"] = "Zähme {npc:250874}",
		["Tame {npc:251707}"] = "Zähme {npc:251707}",
		["Tame {npc:254588}"] = "Zähme {npc:254588}",
		["Tell {npc:252800} you're ready"] = "Sag {npc:252800}, dass du bereit bist",
		["The Al'Aketh camp"] = "Das Lager der Al'Aketh",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "Die Rohen Windsteine sind blaue Kristalle an den Hängen rund ums Dorf.",
		["The orchard"] = "Der Obstgarten",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "Die Königin schwebt am Südostende des Hains, auf deinem Rückweg von den Steinen.",
		["The refugees' belongings lie along the north shore of {area:16625}; {npc:259013} is at its north-west end."] = "Die Habseligkeiten der Flüchtlinge liegen am Nordufer von {area:16625}; {npc:259013} ist an seinem Nordwestende.",
		["The standing stones"] = "Die Menhire",
		["The turncoat"] = "Der Überläufer",
		["The turncoat's house is in the {area:16626} north-west of {area:16638}. {npc:273017} waits nearby; his assassins lurk around the house."] = "Das Haus des Überläufers ist in {area:16626} nordwestlich von {area:16638}. {npc:273017} wartet in der Nähe; seine Attentäter lauern ums Haus.",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629} liegt nördlich von {area:16638}. Kämpf dich durch die Wachen hinauf zu {npc:253576} auf seiner Ostseite.",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Benutze {item:278078} an der Zeremonienmatte und dem Räuchergefäß an der Südklippe der {area:1641}.",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "Du verlässt die Insel endgültig. {npc:259119} wartet, wo das Luftschiff landet.",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "Du wachst in {area:16635} auf, im Norden der Insel. {npc:251362} steht am Pfad, {npc:251361} in der Dorfmitte.",
		["search the dead cultist in the house"] = "durchsuch den toten Kultisten im Haus",
		["search the wardrobe"] = "durchsuch den Kleiderschrank",
		["talk to {npc:251684}"] = "sprich mit {npc:251684}",
		["talk to {npc:251902}"] = "sprich mit {npc:251902}",
		["talk to {npc:251968}"] = "sprich mit {npc:251968}",
		["talk to {npc:252155}"] = "sprich mit {npc:252155}",
		["talk to {npc:252476}"] = "sprich mit {npc:252476}",
		["talk to {npc:257554}"] = "sprich mit {npc:257554}",
		["the bounty board"] = "das Kopfgeldbrett",
		["{area:16624} turn-ins"] = "Abgaben in {area:16624}",
		["{area:16635} turn-ins"] = "Abgaben in {area:16635}",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663} liegt westlich von {area:16638} an der Küstenstraße.",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105} wächst um {npc:257944}s Lager, und Kreischlinge fliegen darüber. Das Lager der Al'Aketh östlich von ihr enthält {item:265141}.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, von {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, von {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, von {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, von {npc:3027}",
		["{npc:251361}'s errands"] = "{npc:251361}s Besorgungen",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: eine Notiz von deinem Lehrer",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}: Untersuche {item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: Lies {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, der Druidenlehrer, im Erdgeschoss des Baums hinter {npc:251361}",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}: {npc:5873} und dein {item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, im Wachturm",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, im Wachturm",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {npc:2523}, dein {item:5176} und {item:263412}",
		["{npc:252448} and {npc:256083}"] = "{npc:252448} und {npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}, {npc:258130} und {npc:258134} sind im Kultlager östlich von {npc:257944}. {npc:254151} steht an seinem Rand. Haalien lässt auch {quest:94490} fallen: Lies ihn, um die nächste Quest zu starten. Für {quest:94489} betrittst du den Nachtfangbau, heilst 7 verletzte Druiden und findest {npc:258130}.",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} lauert südlich des Dorfs zwischen den Rudelkrallen. {npc:254589} ist Elite: Such dir am besten eine Gruppe.",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083} steht in {area:16626} gleich nordwestlich der Stadt.",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247} wartet auf der Straße nördlich von {area:16638}, Richtung {area:16629}.",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196} hält {item:263993} auf der Westseite des Schreins.",
		["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "{npc:257554} und {npc:263113} stehen oben auf dem Wachturm, ein paar Schritte nordöstlich von {npc:251368}.",
		["{npc:257944} again"] = "Wieder {npc:257944}",
		["{npc:257944}, last time"] = "{npc:257944}, ein letztes Mal",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "{npc:259118}, bei der Landestelle: für {npc:3033} in {zone:1456}",
		["{npc:259119}: keep it, Thrall in {zone:1454} comes two guides later"] = "{npc:259119}: Behalte sie, Thrall in {zone:1454} kommt zwei Guides später",
		["{npc:263664}'s campfire"] = "{npc:263664}s Lagerfeuer",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} will Taurenweihrauch: Kauf seine vier Teile bei {npc:3014}, der Kräuterhändlerin, {npc:3012}, der Händlerin für Verzauberkunstbedarf, {npc:3005}, dem Händler für Lederverarbeitungsbedarf, und {npc:3027}, dem Händler für Kochbedarf, und kombiniere sie dann zu {item:278078}.",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529} liegt südlich von Shen'dar. {npc:257065} trifft dich an seinem Rand; durchsuch den Kleiderschrank im Haus hinter ihm.",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "Zurück nach Osten zur {area:358}: Die Schamanen der Borstennacken stehen dort zwischen den Stacheleber.",
		["Back south-east to the {area:396}."] = "Zurück nach Südosten zum {area:396}.",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "Zurück zu {npc:5888} im Lager. {npc:5891} wartet auf dem Tafelberg östlich des Lagers: Trink dort {item:6635}, um sie zu sehen, und bring dann {item:6656} zurück zum Seher.",
		["Back west to the camp."] = "Zurück nach Westen zum Lager.",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "Kampfeber grasen nördlich des Schreins; die Stacheleber der Borstennacken halten die Schlucht im Nordosten. {npc:8554} steht an ihrem östlichen Ende, und {object:3076} liegt im Lager auf dem Boden.",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "Zieh nach Nordwesten an {zone:1456} vorbei zum {area:398} im äußersten Norden von {zone:1412}.",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "Folge dem Pfad nach Süden aus dem Lager zum Zelt des Sehers am Fuß der Hügel.",
		["Galak centaurs"] = "Zentauren der Galak",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "Geh nach Norden zu {area:225}, östlich von {zone:1456}. {npc:3233} steht am Fuß der Felsen; die Eindringlinge der Borstennacken graben auf der Grabstätte, und {npc:2994} wartet oben.",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "Präriewolfalphas streifen zwischen den Wölfen auf den Ebenen um {npc:275789} und das Lager der Galak im Osten umher.",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "Präriewölfe und Erwachsene Ebenenschreiter streifen über die Ebenen ums Dorf.",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "Fahr mit einem Aufzug hinauf zu den Tafelbergen. {npc:2995} hält die Windreiter auf der mittleren Anhöhe; {npc:3057} steht dort im großen Zelt.",
		["Spread the {item:278078} off {area:1641}"] = "Verstreu {item:278078} von der {area:1641}",
		["Swoops glide over the plains all around Bloodhoof."] = "Sturzflieger gleiten überall um Bloodhoof über die Ebenen.",
		["Tame it with the {item:15908}"] = "Zähm ihn mit {item:15908}",
		["The Galak centaurs camp on the plains east of the well; {npc:275767} leads them."] = "Die Zentauren der Galak lagern auf den Ebenen östlich des Brunnens; {npc:275767} führt sie an.",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "Die Gnolle der Bleichmähnen halten den {area:818}, südlich der Grabungsstätte und westlich von Bloodhoof. {npc:272203} wird in ihrem Lager festgehalten: Führ ihn hinaus.",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "Die Harpyien der Windfurien halten {area:819}, nördlich und westlich des Brunnens.",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "Die Zwerge der {area:404} tragen die Ausgrabungsleiterhacken. Zerschlag sie an der Schmiede der Zwerge in der Ausgrabungsstätte.",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "Die Goblins arbeiten in der Mine in den Hügeln nordöstlich des Brunnens. {quest:765} steht hinten in der Mine; seine {item:281031} starten {quest:98424}, und die anderen Seiten liegen in der Mine.",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "Der Weihrauch brennt in zehn Minuten ab: Lauf an den südlichen Hügeln entlang direkt nach Osten zum {object:660739}.",
		["The shrine of An'she and Mu'sha"] = "Der Schrein von An'she und Mu'sha",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "Der Stein steht im Pass aus {zone:1412} hinaus, auf deinem Weg nach Osten. Benutze dort {item:15710} und besiege Mondklaue.",
		["The well lies south-east of the village."] = "Der Brunnen liegt südöstlich des Dorfs.",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "Die zerstörte Karawane liegt nordwestlich der Zentauren, östlich der Straße nach {zone:1456}.",
		["The {object:177525}"] = "{object:177525}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "Benutze {item:278078} an der Zeremonienmatte und dem Räuchergefäß an der Südklippe der {area:1641}.",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "Du beginnst auf dem Tafelberg von {area:221}. {npc:2980} und der Häuptling stehen beim großen Zelt in der Mitte.",
		["{item:278079}, from {npc:3014}"] = "{item:278079}, von {npc:3014}",
		["{item:278080}, from {npc:3012}"] = "{item:278080}, von {npc:3012}",
		["{item:278081}, from {npc:3005}"] = "{item:278081}, von {npc:3005}",
		["{item:278083}, from {npc:3027}"] = "{item:278083}, von {npc:3027}",
		["{item:4703}, at the digsite forge"] = "{item:4703}, an der Schmiede der Ausgrabungsstätte",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}: Flachlandstreuner streifen über die Ebenen um {area:225}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068} will Taurenweihrauch: Kauf seine vier Teile bei {npc:3014}, der Kräuterhändlerin, {npc:3012}, der Händlerin für Verzauberkunstbedarf, {npc:3005}, dem Händler für Lederverarbeitungsbedarf, und {npc:3027}, dem Händler für Kochbedarf, und kombiniere sie dann zu {item:278078}.",
		["{npc:275789} stands on the {area:821} a little east of the well."] = "{npc:275789} steht auf den {area:821} ein Stück östlich des Brunnens.",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182} steht am Nordrand des Dorfs. Kyle will {item:287505} von Ebenenschreitern.",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}, am Nordende des Dorfs",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}, für Hamuul in {zone:1456}",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984} steht am Rand der {area:404}, südlich des Brunnens.",
		["{npc:2988} camps by the {area:396} south-east of Bloodhoof."] = "{npc:2988} lagert beim {area:396} südöstlich von Bloodhoof.",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991} sitzt beim Zelt am Ostrand des Lagers; {object:2907} steht neben ihr.",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}, für {npc:3057} in {zone:1456}",
		["{npc:3060}, the druid trainer beside him"] = "{npc:3060}, der Druidenlehrer neben ihr",
		["{npc:3061}, the hunter trainer"] = "{npc:3061}, die Jägerlehrerin",
		["{npc:3062}, the shaman trainer in camp"] = "{npc:3062}, die Schamanenlehrerin im Lager",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "Die Quest von {npc:3063}: Besiege drei Kriegernovizen (oder Spieler im Duell) neben ihm.",
		["{npc:3441}: for {quest:860} at the {area:380}"] = "{npc:3441}: für {quest:860} in {area:380}",
		["{npc:5769}: for {npc:3448} at the {area:380}"] = "{npc:5769}: für {npc:3448} in {area:380}",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888} steht im {area:221}. {quest:1516} erfordert Stufe 4, die du mit den Abgaben hier erreichst.",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}: {npc:5873} und dein {item:5175}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775} steht am Westende des Lagers, an der Nordwestecke der Hügel, wo die Bergpumas umherstreifen: Nimm seine Quest an, jag die Pumas von dort nach Süden und Osten und komm dann zurück hinauf zu {npc:2980}.",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "{quest:96130}, ein einsamer Wolf, streift über die Ebenen westlich des Dorfs. Präriepirscher und Flachlandpumas streifen über die Ebenen nördlich und westlich davon.",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Back east to the shore north of {npc:275657}. Spitelash Scouts and Attendants hold the beach below {area:370}. Hunters: tame a {npc:3107} on the beach."] = "Zurück nach Osten zum Ufer nördlich von {npc:275657}. Späher und Bedienstete der Grollflossen halten den Strand unterhalb von {area:370}. Jäger: Zähm am Strand einen {npc:3107}.",
		["Back south to {area:362}."] = "Zurück nach Süden nach {area:362}.",
		["Back to the Den"] = "Zurück zum Höhlenbau",
		["Back to {area:362}."] = "Zurück nach {area:362}.",
		["Back to {npc:5875} in the {object:172960}. Use the {item:7464} on the summoning circle there and defeat the voidwalker to bind it."] = "Zurück zu {npc:5875} in {object:172960}. Benutze dort {item:7464} am Beschwörungskreis und besiege den Leerwandler, um ihn zu binden.",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "Kultisten der Burning Blade halten die Höhlen von {quest:827}; jeder lässt {item:4871} fallen. {npc:3204}, ein Hexenmeister der Stufe 14, steht tief drinnen und lässt {item:4903} fallen.",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "Teufelspirscher streifen über den Hang unterhalb der Höhle, auf der Nordseite des Tals.",
		["Follow the road east out of the valley to {area:367} on the coast."] = "Folge der Straße nach Osten aus dem Tal nach {area:367} an der Küste.",
		["Free {npc:275811} and see her safely out of the crag"] = "Befrei {npc:275811} und bring sie sicher aus dem Felsen",
		["Head north-east to the road toward {zone:1454}. {npc:3293} camps beside it; the stolen sacks lie along the road south of him."] = "Geh nach Nordosten zur Straße Richtung {zone:1454}. {npc:3293} lagert daneben; die gestohlenen Säcke liegen entlang der Straße südlich von ihm.",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "Geh in der Höhle an der ersten Gabelung geradeaus, dann rechts, und folge dem Bach zu deiner Linken bis zum Wasserfall: Die Hacke leuchtet am Wasser, hinter einer Felssäule.",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "Halte dich in der Höhle immer an der rechten Wand, über den Bach: {npc:3183} wartet am Ende.",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "Mishas Hütte steht südlich der Echsen. Die Krokilisken am {area:814} im Westen tragen {item:4891}.",
		["Prickly pears"] = "Kaktusfeigen",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "Stacheleber und Späher halten die Hütten westlich des Orts; Staubläufer und Schlachtwachen halten die Lager weiter westlich.",
		["Spitelash naga"] = "Naga der Grollflossen",
		["Tame it with the {item:15908}"] = "Zähm ihn mit {item:15908}",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "Die Burg steht an der Küste südöstlich von {area:362}. Axt, Bogen und Schild der Räuber liegen an ihrem Rand. Matrosen und Marinesoldaten lassen {item:4870} fallen. {npc:3192} wartet oben in der Burg; sein Schlüssel öffnet die Truhe neben ihm, in der {item:4881} liegt.",
		["The prickly pears grow among the quilboar huts just west of town."] = "Die Kaktusfeigen wachsen zwischen den Hütten der Stacheleber gleich westlich des Orts.",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "Die Waffen liegen um den Höhlenbau und den Übungsplatz; die Scheckigen Eber streifen über den ganzen Talboden.",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595} steht in {area:817}, zwischen den Kultisten, die du gerade bekämpft hast.",
		["Thunder Lizards and Lightning Hides graze on {area:369} across the bridge; any of them can drop a {item:6486}."] = "Donnerechsen und Blitzechsen grasen jenseits der Brücke auf dem {area:369}; jede kann {item:6486} fallen lassen.",
		["Thunder lizards across the river"] = "Donnerechsen jenseits des Flusses",
		["Training weapons and boars"] = "Übungswaffen und Eber",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there."] = "Wate hinüber zur nördlichen Echoinsel. Die Matriarchin streift dort zwischen den Raptoren umher.",
		["Wake {quest:5441} with the {item:16114}"] = "Weck {quest:5441} mit {item:16114}",
		["the {object:654925} on the ground beside her"] = "{object:654925} neben ihr auf dem Boden",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366} liegt westlich von Sen'jin. Die drei Angriffspläne liegen zwischen den Zentaurenzelten auf dem Boden. {npc:275811} wird ebenfalls am Felsen festgehalten.",
		["{area:817}'s mouth"] = "Eingang von {area:817}",
		["{npc:10176}, where you start"] = "{npc:10176}, wo du startest",
		["{npc:265809}'s campfire"] = "Lagerfeuer von {npc:265809}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}: nur für Verzauberer, die Rückstände werden aus Verhexten Anhängern ({item:275724}) entzaubert",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657} steht am Ufer östlich von {area:362}. Dreizack, Banner und Dolch liegen um ihn herum am Strand.",
		["{npc:3102} hooves"] = "{npc:3102}-Hufe",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}, zurück in {area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}: {npc:275666}, ein Elite-Meeresriese",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143} steht gleich hinter dem Höhleneingang; {npc:3159} hinten in der Höhle hinter ihm.",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143} wartet im Höhlenbau, dem Gebäude gleich westlich von {npc:10176}.",
		["{npc:3147}, in the watchtower"] = "{npc:3147}, im Wachturm",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287} liegt verwundet am Fuß der Hügel nordwestlich des Höhlenbaus.",
		["{npc:3294}, by the inn"] = "{npc:3294}, beim Gasthaus",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}, für {npc:6018} in {zone:1454}: behalte sie",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}, der Priesterlehrer am Höhlenbau",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887} steht vor dem Höhlenbau. {area:639} ist der Hügel gleich südlich davon: Trink dort {item:6635}, um {npc:5891} zu sehen, und bring dann {item:6656} zurück zu {npc:5887}.",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}: {npc:5873} und dein {item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}, auf dem {area:639}",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786} steht auf der Straße am östlichen Ausgang des Tals.",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}, am Kochfeuer",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828} lagert auf dem Hügel westlich des Nagastrands, südlich von {quest:827}.",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "Das Haupttor von {zone:1454} liegt gleich westlich von {area:817}. {npc:5875} steht in {object:172960}, der Schlucht unter dem {object:172982}.",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
		["Ask {npc:10666} for his report"] = "Bitte {npc:10666} um seinen Bericht",
		["Ask {npc:1496} for his report"] = "Bitte {npc:1496} um seinen Bericht",
		["Ask {npc:251001} for his report"] = "Bitte {npc:251001} um seinen Bericht",
